            /////////////////////////////////////////////////////////////////////////////////////	
            public bool AddOnLineInData_GR(DataTable dtStorage)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddOnLineInData_GR";
                this.ControlMethodParm = "('')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                int CountAlQty = 0;
                int QueryMblnrQty = 0;
                int QueryGrdQty = 0;
                int QueryGrdMblnrQty = 0;
                string strMblnr = "";
                string strCharg = "";
                string strInsmk = "";
                string strDacod = "";
                ArrayList arySQL = new ArrayList();
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhgrd objWhgrd = new DataWhgrd(UserData);
                DataWhdwn objWhdwn = new DataWhdwn(UserData);

                QCI.QWMS.StorageData objStorage = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);

                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    strMblnr = dtStorage.Rows[0]["MBLNR"].ToString();
                    strInsmk = dtStorage.Rows[0]["INSMK"].ToString();
                    strCharg = dtStorage.Rows[0]["CHARG"].ToString();
                    strDacod = dtStorage.Rows[0]["DACOD"].ToString();

                    //計算目前所有輸入Item的總數量  Smose Liao 200090514
                    CountAlQty += int.Parse(dtStorage.Rows[i]["ALQTY"].ToString());

                    //查詢已存於dbo.WHGRD的數量  Smose Liao 20090514
                    QueryGrdQty = objStorage.QueryGrdQty(strMblnr, strInsmk, strCharg, strDacod);

                    if (dtStorage.Columns.IndexOf("KDMAT") == -1)
                    {
                        //strSQL = "Insert into WHGRD(MANDT, WERKS, LGORT, MATNR, INSMK, MBLNR, CHARG, LIFNR, EBELN, INDAT, LODAT, MENGE, QCQTY, REFNO, MRGID, ISPTM, RMAK1,CRNAM, CRDAT, MONAM, MODAT, DACOD, LOCOD, INSPT, VEDAT) " +
                        //    "values('" + dtStorage.Rows[i]["MANDT"].ToString() + "', '" + dtStorage.Rows[i]["WERKS"].ToString() + "','" + dtStorage.Rows[i]["LGORT"].ToString() + "','" +
                        //    dtStorage.Rows[i]["MATNR"].ToString() + "','" + dtStorage.Rows[i]["INSMK"].ToString() + "','" + dtStorage.Rows[i]["MBLNR"].ToString() + "','" +
                        //    dtStorage.Rows[i]["CHARG"].ToString() + "','" + dtStorage.Rows[i]["LIFNR"].ToString() + "','" + dtStorage.Rows[i]["EBELN"].ToString() + "','" + dtStorage.Rows[i]["INDAT"].ToString() + "','" + dtStorage.Rows[i]["LODAT"].ToString() + "'," +
                        //    dtStorage.Rows[i]["ALQTY"].ToString() + ", 0, '', '', '','" + dtStorage.Rows[i]["RMAK1"].ToString() + "','" + CRNAM + "', getdate() ,'" + CRNAM + "', getdate(),'" + dtStorage.Rows[i]["DACOD"].ToString() + "','" + dtStorage.Rows[i]["LOCOD"].ToString() + "','" + dtStorage.Rows[i]["INSPT"].ToString() + "','" + dtStorage.Rows[i]["VEDAT"].ToString() + "')";
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhdwn.ResetField();
                        objWhgrd.Mandt = dtStorage.Rows[i]["MANDT"].ToString();
                        objWhgrd.Comcd = COMCD;
                        objWhgrd.Werks = dtStorage.Rows[i]["WERKS"].ToString();
                        objWhgrd.Lgort = dtStorage.Rows[i]["LGORT"].ToString();
                        objWhgrd.Matnr = dtStorage.Rows[i]["MATNR"].ToString();
                        objWhgrd.Insmk = dtStorage.Rows[i]["INSMK"].ToString();
