                    //strSQL = "Update WHDWN set OTQTY=OTQTY+ " + dtStorage.Rows[i]["MENGE"].ToString() + " where MANDT= '" + MANDT + "' and MBLNR= '" + dtStorage.Rows[i]["MBLNR"].ToString() + "' and ZEILE= '" + dtStorage.Rows[i]["ZEILE"].ToString() + "'";
