                    arySQL.Add(strSQL);

                    //WHGRR 儲存入庫單資料(廠商生產日期改存到VEDAT欄位；DateCode改存到Dacod欄位)  Smose Liao 20091020
                    //strSQL = "Insert into WHGRR(GRRNO, ITEMNUM, MANDT, WERKS, LGORT, LOCAT, MATNR, MBLNR, INSMK, CHARG, LIFNR, EBELN, TRNTP, VEDAT, BKQTY, DACOD, LOCOD, INSPT, BARCODE, PRTYP, CTRLNM) " +
                    //    "values('" + strGRRNO + "','" + (i + 1) + "','" + dtStorage.Rows[i]["MANDT"].ToString() + "', '" + dtStorage.Rows[i]["WERKS"].ToString() + "','" + dtStorage.Rows[i]["LGORT"].ToString() + "','" +
