                    //    dtStorage.Rows[i]["DACOD"].ToString() + "','" + dtStorage.Rows[i]["LOCOD"].ToString() + "','" + dtStorage.Rows[i]["INSPT"].ToString() + "','" + (strGRRNO + (Itemnum)) + "', 0, 'INAUT')";

                    //arySQL.Add(strSQL);
