            //====================================================================================
            ////////////Summary by Smose Liao 20090605////////////////////////////////////////////
            /// <summary>
            /// EC單比對
            /// </summary> 
            /// <param name="dtStorage">EC單資料。</param>
            /// <returns>
            /// bool。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  bool  bolReturn = objStorageIn.AddOnLineInEC_Document(dtStorage);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////	
            public bool AddOnLineInEC_Document(DataTable dtStorage)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddOnLineInEC_Document";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                ArrayList arySQL = new ArrayList();
                //string strSQL = "";
                string strLocat = "";
                bool bolReturn = false;
                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                DataWhecd ojbWhecd = new DataWhecd(UserData);
                DataWhhed ojbWhhed = new DataWhhed(UserData);

                QCI.QWMS.StorageData objStorage = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);

                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    if (!objStorage.QueryDocumentExistsInStorage(dtStorage.Rows[i]["VBELN"].ToString()))
                    {
                        //WHECD
                        //strSQL = "Insert into WHECD(MANDT, WERKS, LGORT, VBELN, PAKID, LOCAT, MATNR, MENGE, BATCH, EBELN) " +
                        //    "values('" + dtStorage.Rows[i]["MANDT"].ToString() + "', '" + dtStorage.Rows[i]["WERKS"].ToString() + "','" + dtStorage.Rows[i]["LGORT"].ToString() + "', '" + dtStorage.Rows[i]["VBELN"].ToString() + "','" + dtStorage.Rows[i]["PAKID"].ToString() + "','" + dtStorage.Rows[i]["LOCAT"].ToString() + "','" + dtStorage.Rows[i]["MATNR"].ToString() + "','" + dtStorage.Rows[i]["MENGE"].ToString() + "','" + dtStorage.Rows[i]["BATCH"].ToString() + "','" + dtStorage.Rows[i]["EBELN"].ToString() + "')";
                        //arySQL.Add(strSQL);
                        alColumns.Clear();
                        alConditions.Clear();
                        ojbWhecd.ResetField();

                        ojbWhecd.Mandt = dtStorage.Rows[i]["MANDT"].ToString();
                        ojbWhecd.Comcd = dtStorage.Rows[i]["COMCD"].ToString();
                        ojbWhecd.Werks = dtStorage.Rows[i]["WERKS"].ToString();
                        ojbWhecd.Lgort = dtStorage.Rows[i]["LGORT"].ToString();
                        ojbWhecd.Vbeln = dtStorage.Rows[i]["VBELN"].ToString();
                        ojbWhecd.Pakid = dtStorage.Rows[i]["PAKID"].ToString();
                        ojbWhecd.Locat = dtStorage.Rows[i]["LOCAT"].ToString();
                        ojbWhecd.Matnr = dtStorage.Rows[i]["MATNR"].ToString();
                        ojbWhecd.Menge = dtStorage.Rows[i]["MENGE"].ToString();
                        ojbWhecd.Batch = dtStorage.Rows[i]["BATCH"].ToString();
                        ojbWhecd.Ebeln = dtStorage.Rows[i]["EBELN"].ToString();

                        arySQL.Add(ojbWhecd.EntityGetInsertSql());

                        bolReturn = true;
                    }
                    else
                    {
                        bolReturn = false;
                        break;
                    }
                }

                try
                {
                    if (bolReturn == false)
                    {
                        ERRMSG = "這筆EC單已經處理過，請確認!!";
                    }
                    else
                    {
                        if (dtStorage.Rows[0]["LOCAT"].ToString().Trim() != "")
                        {
                            //檢查儲位是否已經存在
                            if (!objStorage.QueryLocationExistsInStorage(dtStorage.Rows[0]["WERKS"].ToString(), dtStorage.Rows[0]["LGORT"].ToString(), dtStorage.Rows[0]["LOCAT"].ToString()))
                            {
                                //自動建立儲位
                                strLocat = dtStorage.Rows[0]["LOCAT"].ToString();
                                //strSQL = "Insert into WHHED(MANDT, WERKS, LGORT, LOCAT, LOSTS) " +
                                //    "values('" + dtStorage.Rows[0]["MANDT"].ToString() + "', '" + dtStorage.Rows[0]["WERKS"].ToString() + "','" + dtStorage.Rows[0]["LGORT"].ToString() + "','" + strLocat.Substring(0, 10) + "', '0')";

                                //arySQL.Add(strSQL);

                                alColumns.Clear();
                                alConditions.Clear();
                                ojbWhecd.ResetField();

                                ojbWhhed.Mandt = dtStorage.Rows[0]["MANDT"].ToString();
                                ojbWhhed.Comcd = dtStorage.Rows[0]["COMCD"].ToString();
                                ojbWhhed.Werks = dtStorage.Rows[0]["WERKS"].ToString();
                                ojbWhhed.Lgort = dtStorage.Rows[0]["LGORT"].ToString();
                                ojbWhhed.Locat = strLocat.Substring(0, 10);
                                ojbWhhed.Losts = "0";

                                arySQL.Add(ojbWhhed.EntityGetInsertSql());
                            }

                            ControlHandleDB();
                            bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                            ControlSqlAccess.CloseConnection();
                        }
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
