                                    objWhitm.LOCKED = "Y";
                                    objWhitm.LKDAT = "GetDate()";
                                }
                            }
                            else
                            {
                                objWhitm.LOCKED = "Y";
                                objWhitm.LKDAT = "GetDate()";

                            }
                        }
                        if (dtStorage.Columns.IndexOf("CONFIG") != -1)
                        {
                            objWhitm.Config = dtStorage.Rows[i]["CONFIG"].ToString();
                        }
                        strSQL = objWhitm.EntityGetInsertSql();
                        arySQL.Add(strSQL);

                        //strSQL = "Insert into WHITM(MANDT, COMCD,WERKS, LGORT, LOCAT, MATNR, INSMK, MBLNR, CHARG, LIFNR, EBELN, INDAT, MENGE, QCQTY, REFNO, MRGID, ISPTM, RMAK1,CRNAM, CRDAT, MONAM, MODAT) " +
                        //    "values('" + dtStorage.Rows[i]["MANDT"].ToString() + "','" + dtStorage.Rows[i]["COMCD"].ToString() + "', '" + dtStorage.Rows[i]["WERKS"].ToString() + "','" + dtStorage.Rows[i]["LGORT"].ToString() + "','" +
                        //    dtStorage.Rows[i]["LOCAT"].ToString() + "','" + dtStorage.Rows[i]["MATNR"].ToString() + "','" + dtStorage.Rows[i]["INSMK"].ToString() + "','" + dtStorage.Rows[i]["MBLNR"].ToString() + "','" +
                        //    dtStorage.Rows[i]["CHARG"].ToString() + "','" + dtStorage.Rows[i]["LIFNR"].ToString() + "','" + dtStorage.Rows[i]["EBELN"].ToString() + "','" + dtStorage.Rows[i]["INDAT"].ToString() + "'," +
                        //    dtStorage.Rows[i]["ALQTY"].ToString() + ", 0, '', '', '','" + dtStorage.Rows[i]["RMAK1"].ToString() + "','" + CRNAM + "', getdate() ,'" + CRNAM + "', getdate())";

                    }
                    else
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhitm.ResetField();

                        objWhitm.Menge = "MENGE +" + dtStorage.Rows[i]["ALQTY"].ToString();
                        objWhitm.Rmak1 = dtStorage.Rows[i]["RMAK1"].ToString();
                        objWhitm.Monam = CRNAM;
