                        {
                            alConditions.Add("Mblnr= '" + dtStorage.Rows[i]["OMBLNR"].ToString() + "'");
                        }
                        else
                        {
                            alConditions.Add("Mblnr= '" + dtStorage.Rows[i]["MBLNR"].ToString() + "'");
                        }
                        alConditions.Add("Charg= '" + dtStorage.Rows[i]["CHARG"].ToString() + "'");

                        strSQL = objWhitm.EntityGetUpdateSql(alConditions);

                        //strSQL = "Update WHITM set MENGE= MENGE + " + dtStorage.Rows[i]["ALQTY"].ToString() + ", RMAK1='" + dtStorage.Rows[i]["RMAK1"].ToString() + "', MONAM= '" + CRNAM + "', MODAT=getdate() where MANDT= '" + dtStorage.Rows[i]["MANDT"].ToString() + "' and COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "' and WERKS='" + dtStorage.Rows[i]["WERKS"].ToString() +
                        //    "' and LGORT= '" + dtStorage.Rows[i]["LGORT"].ToString() + "' and LOCAT= '" + dtStorage.Rows[i]["LOCAT"].ToString() + "' and MATNR= '" + dtStorage.Rows[i]["MATNR"].ToString() + "' and INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() +
                        //    "' and MBLNR= '" + dtStorage.Rows[i]["MBLNR"].ToString() + "' and CHARG= '" + dtStorage.Rows[i]["CHARG"].ToString() + "'";

                        arySQL.Add(strSQL);
