            #region WriteSapFile_ZRFC_GET_SMT_STOCK(產生查詢庫存數量的TXT文檔)
            //===========================================================================
            ////////////Summary by Smose Liao////////////////////////////////////////////
            /// <summary>
            /// 產生查詢庫存數量的TXT文檔
            /// </summary> 
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /////////////////////////////////////////////////////////////////////////////   
            public void WriteSapFile_ZRFC_GET_SMT_STOCK(DataTable dtRequest)
            {
                Qci.Base.Common.FileAccess objFile = new FileAccess(strFileInPath, strSAPUser, strPwd);

                //有幾個string類型的輸入參數這邊就宣告幾個ArrayList
                ArrayList[] alStr = new ArrayList[0];
                DataTable dtTemp = new DataTable();

                //有幾備個ref table的輸入參數這邊就宣告幾個Array List
                ArrayList[] alTable = new ArrayList[1];

                alTable[0] = new ArrayList();

                alTable[0].Add("ITABIN");
                alTable[0].Add(dtRequest);

                //取得現在系統的時間
                string strDateTime = DateTime.Now.ToString("yyyyMMddHHmmssffff");
                //產生文檔的檔名
                strFileName = "EC025_" + objFile.GetGuid() + ".txt";  //以前都是yyyyMMddHHmmssffff，現在直接Get guid

                objFile.WriteSapFile(alStr, alTable, strFileInPath, strFileName, true);

            }
            #endregion

            #region ReadSapFile_ZRFC_GET_SMT_STOCK(讀取SAP回傳庫存數量的TXT文檔)
            //===========================================================================
            ////////////Summary by Smose Liao////////////////////////////////////////////
            /// <summary>
            /// 讀取SAP回傳庫存數量的TXT文檔
            /// </summary> 
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /////////////////////////////////////////////////////////////////////////////   
            public DataTable ReadSapFile_ZRFC_GET_SMT_STOCK()
            {
                Qci.Base.Common.FileAccess objFile = new FileAccess(strFileOutPath, strSAPUser, strPwd);

                ArrayList aryString = new ArrayList();
                ArrayList aryTable = new ArrayList();
                DataTable dtReturn = new DataTable();

                aryTable.Add("ITABIN");

                dtReturn.TableName = "SAP";
                DataColumnCollection columns = dtReturn.Columns;
                columns.Add("PLANT", typeof(System.String));         //廠區
                columns.Add("LOCATION", typeof(System.String));      //倉別
                columns.Add("MATERIAL", typeof(System.String));      //料號
                columns.Add("STOCK", typeof(System.Decimal));　　　　//庫存
                columns.Add("ROUNDING", typeof(System.Decimal));     //最小包裝量
                columns.Add("STATUS", typeof(System.String));

                try
                {
                    //檔案名稱只要輸入"abc"，即會抓取abc開頭的檔案進行解析
                    string strFileBackupPath = strFileOutPath + @"\Backup\EC025"; //檔案備份路徑
                    ArrayList[] aryReturn = objFile.ReadSapFile(aryString, aryTable, strFileOutPath, strFileName, 1000, 500000, strFileBackupPath);

                    //此為table的回傳值
                    DataTable dtTemp = (DataTable)(aryReturn[0][1]);

                    for (int i = 0; i < dtTemp.Rows.Count; i++)
                    {
                        DataRow dr = dtReturn.NewRow();
                        dr[0] = dtTemp.Rows[i]["1"].ToString().Trim();
                        dr[1] = dtTemp.Rows[i]["2"].ToString().Trim();
                        dr[2] = dtTemp.Rows[i]["3"].ToString().Trim();
                        dr[3] = dtTemp.Rows[i]["4"].ToString().Trim();
                        dr[4] = dtTemp.Rows[i]["5"].ToString().Trim();
                        dr[5] = dtTemp.Rows[i]["6"].ToString().Trim();
                        dtReturn.Rows.Add(dr);
                    }
                }
                catch (Exception ex)
                {
                    string strErrmsg = ex.Message;
                }

                return dtReturn;
            }
            #endregion

            #region 取得sap連線資料
            //=========================================================================
            ////////////Summary by Rock Tzeng////////////////////////////////////////////
            /// <summary>
            ///取得sap連線資料
            /// </summary> 
            /// <param name="dtStorage">Client。</param>
            /// <returns>
            /// string。
            /// </returns>
            /////////////////////////////////////////////////////////////////////////////   
            public string GetSAPConnection(string strClient)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetSAPConnection";
                this.ControlMethodParm = "('" + strClient + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    StringBuilder sbSql = new StringBuilder();
                    sbSql.Append("Select * from WHCTRL where  ");
                    sbSql.AppendFormat("MANDT='{0}' ", "QCI");
                    sbSql.AppendFormat("and SOLDTO='{0}' ", "QWMS");
                    sbSql.AppendFormat("and CTRLID='{0}' ", "SAP");
                    sbSql.AppendFormat("and CTRLNM='{0}' ", strClient.Trim());

                    string strConnection = "";
                    DataTable dtData = new DataTable();
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                    ControlSqlAccess.CloseConnection();

                    if (dtData.Rows.Count > 0)
                    {
                        strConnection = dtData.Rows[0]["CTRLC1"].ToString();
                    }

                    return strConnection;

                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

            }
            #endregion

