            #region SMT UpdateSAP庫存資訊(透過TXT文檔存取)(連線入庫(SMT))
            //==================================================================================
            ////////////Summary by Smose Liao 20120724//////////////////////////////////////////
            /// <summary>
            /// SMT Update SAP庫存資訊(透過TXT文檔存取)
            /// </summary> 
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            ///////////////////////////////////////////////////////////////////////////////////
            public DataTable wsUpdateSapInventory_SMT_ByTxt(DataTable dtStorage, string strLocat)
            {
                string strError = "";
                string strPost = "";
                string strStatus = "";

                //if (dtStorage.Rows[0]["REFID"].ToString().Substring(0, 3) == "SR-")
                //{
                //    strStatus = "T";  //來源倉別若不為空，則設定傳送的參數為"T"
                //}
                strStatus = "T";//所有的311轉倉資料，Status狀態都需傳'T'  Smose Liao 20130523

                DataTable dtOutTable = new DataTable();
                dtOutTable.TableName = "SAP";
                DataColumnCollection columns = dtOutTable.Columns;
                columns.Add("REFNO", typeof(System.String));         //Reference ID
                columns.Add("PLANT", typeof(System.String));         //廠區
                columns.Add("MATNR", typeof(System.String));         //料號
                columns.Add("KOSTL", typeof(System.String));　　　　 //Cost Center
                columns.Add("LGORTF", typeof(System.String));        //發料倉別
                columns.Add("LGORTT", typeof(System.String));        //入庫倉別
                columns.Add("RETQTY", typeof(System.Decimal));       //數量
                columns.Add("CHARG", typeof(System.String));         //版本
                columns.Add("STATUS", typeof(System.String));        //狀態

                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    DataRow dr = dtOutTable.NewRow();
                    dr[0] = dtStorage.Rows[i]["REFID"].ToString().Trim();
                    dr[1] = dtStorage.Rows[i]["WERKS"].ToString().Trim();
                    dr[2] = dtStorage.Rows[i]["MATNR"].ToString().Trim();
                    dr[3] = dtStorage.Rows[i]["KOSTL"].ToString().Trim();
                    dr[4] = dtStorage.Rows[i]["OTLGT"].ToString().Trim();
                    dr[5] = dtStorage.Rows[i]["LGORT"].ToString().Trim();
                    dr[6] = dtStorage.Rows[i]["MENGE"].ToString().Trim();
                    if (dtStorage.Rows[i]["CHARG"].ToString() != "")//版本
                    {
                        dr[7] = dtStorage.Rows[i]["CHARG"].ToString().Trim();
                    }
                    dr[8] = strStatus;//狀態

                    dtOutTable.Rows.Add(dr);
                }

                DataTable dtResponse = new DataTable();
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);

                try
                {
                    #region 記錄UpdateSapInventory開始的時間  Smose Liao 20100412

                    DataErrlog objErrlog = new DataErrlog(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    ArrayList arySQL = new ArrayList();

                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objErrlog.ResetField();

                        objErrlog.Mandt = dtStorage.Rows[i]["MANDT"].ToString();
                        objErrlog.Mblnr = dtStorage.Rows[i]["DIDNO"].ToString();
                        objErrlog.Matnr = dtStorage.Rows[i]["MATNR"].ToString();
                        objErrlog.Refid = dtStorage.Rows[i]["REFID"].ToString();
                        objErrlog.Comcd = dtStorage.Rows[i]["COMCD"].ToString();
                        objErrlog.Menge = dtStorage.Rows[i]["MENGE"].ToString();
                        objErrlog.Logtim = "GetDate()";
                        objErrlog.Maltim = "GetDate()";
                        objErrlog.Logsql = "UpdateSapInventory()_only" + "/" + strLocat;
                        objErrlog.Usrnm = UserData.UserId.ToString();
                        arySQL.Add(objErrlog.EntityGetInsertSql());
                    }

                    ControlHandleDB();
                    ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();

                    #endregion

                    //產生給SAP扣帳的檔案
                    WriteSapFile_ZRFC_311_AUTO_RETURN(dtOutTable);

                    //讀取SAP回傳的檔案
                    dtResponse = ReadSapFile_ZRFC_311_AUTO_RETURN();//註記部分

                    for (int i = 0; i < dtResponse.Rows.Count; i++)
                    {
                        if (dtResponse.Rows[i]["OMBLN"].ToString() != "")
                        {
                            strPost = dtResponse.Rows[i]["OMBLN"].ToString();
                        }

                        if (dtResponse.Rows[i]["ERRMSG"].ToString() != "")
                        {
                            //Error Message有回傳值，跳出迴圈
                            strError = dtResponse.Rows[i]["ERRMSG"].ToString();
                            break;
                        }
                    }

                    #region 記錄UpdateSapInventory結束的時間  Smose Liao 20100412

                    arySQL.Clear();
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objErrlog.ResetField();

                        objErrlog.Prctim = "GetDate()";
                        alConditions.Add(" MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                        alConditions.Add(" COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                        alConditions.Add(" MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add(" REFID='" + dtStorage.Rows[i]["REFID"].ToString() + "'");
                        alConditions.Add(" MBLNR='" + dtStorage.Rows[i]["DIDNO"].ToString() + "'");

                        arySQL.Add(objErrlog.EntityGetUpdateSql(alConditions));
                    }

                    ControlHandleDB();
                    ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();

                    #endregion
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    strException = ex.Message;
                    throw new Exception(ex.Message);
                }

                #region 比對SAP回傳的錯誤訊息是否含有扣帳編號，有的話取出扣帳編號
                int MathIndex = 0;
                string strDuplicatDoc = "";
                bool bolTryParse = false;
                long outNumber = 0;
                if (strError != "")
                {
                    Regex pattern = new Regex(@"49\d{8}");//比對的pattern，SAP回傳的扣帳編號為49開頭
                    Match m = pattern.Match(strError);

                    #region 檢查SAP回傳的扣帳編號是否全為數值型態，避免誤判抓到料號的情況下，誤入了QWMS庫存
                    //【例】SAP回傳的錯誤訊息：3VPJ7AB0000F3AFD Material Batch is not mapping with WO
                    while (m.Success)
                    {
                        MathIndex = m.Index;//取得SAP回傳的扣帳編號之所在的位置
                        bolTryParse = long.TryParse(strError.Substring(MathIndex, 10), out outNumber);

                        if (bolTryParse == false)
                        {
                            strDuplicatDoc = "";
                            m = m.NextMatch();//往下一筆繼續搜尋
                        }
                        else
                        {
                            strDuplicatDoc = outNumber.ToString();//搜尋成功，取出SAP回傳的扣帳編號
                        }

                        if (strDuplicatDoc != "")
                        {
                            break;//搜尋成功，跳出while迴圈不再搜尋
                        }
                    }
                    #endregion
                }
                #endregion

                #region 把扣帳編號加入原始的Table
                if (strPost.Trim() != "")
                {
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        dtStorage.Rows[i]["OMBLN"] = strPost;
                    }
                }
                else
                {
                    //SAP已扣帳成功並回傳扣帳編號，但QWMS未扣帳成功
                    if (int.Parse(dtStorage.Rows[0]["OTQTY"].ToString()) == 0 && strDuplicatDoc != "")
                    {
                        for (int i = 0; i < dtStorage.Rows.Count; i++)
                        {
                            dtStorage.Rows[i]["OMBLN"] = strDuplicatDoc;
                        }

                        strError = "";//清空strError
                    }

                    if (strError.Trim() == "")
                    {
                        if (strException != "")
                        {
                            ERRMSG = " SAP Error : Can not post(" + this.MANDT + ")-" + strException + "<- wsUpdateSapInventory_SMT_ByTxt()";
                        }
                    }
                    else
                    {
                        ERRMSG = " SAP Error : " + this.MANDT + " " + strError + "<- wsUpdateSapInventory_SMT_ByTxt()";
                    }
                }

                #endregion

                return dtStorage;
            }

