            #region Insert SMT的SAP庫存資訊
            //====================================================================================
            ////////////Summary by Smose Liao 20100916////////////////////////////////////////////
            /// <summary>
            /// Insert SMT的SAP庫存資訊
            /// </summary> 
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /////////////////////////////////////////////////////////////////////////////////////   
            public DataTable InsertSMTSapInventory(DataTable dtStorage)
            {
                DataTable dtOutTable = new DataTable();
                DataTable dtReturn = new DataTable(); //SAP回傳的DataTable
                dtOutTable.TableName = "Return";
                DataColumnCollection columns = dtOutTable.Columns;
                columns.Add("GROUPID", typeof(System.String));      //Group ID
                columns.Add("PLANT", typeof(System.String));        //廠區
                columns.Add("COSTCENTER", typeof(System.String));   //Cost Center
                columns.Add("MATERIAL", typeof(System.String));     //料號
                columns.Add("LGORT", typeof(System.String));        //倉別
                columns.Add("RNDQTY", typeof(System.Int32));        //卷數
                columns.Add("TOTALQTY", typeof(System.Decimal));    //總需求量
                columns.Add("STATUS", typeof(System.String));       //狀態


                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    DataRow dr = dtOutTable.NewRow();
                    dr[0] = dtStorage.Rows[i]["GRPID"].ToString().Trim();//Reference No.					 
                    dr[1] = dtStorage.Rows[i]["WERKS"].ToString().Trim();//廠區
                    dr[2] = dtStorage.Rows[i]["KOSTL"].ToString().Trim();//Cost Center
                    dr[3] = dtStorage.Rows[i]["MATNR"].ToString().Trim();//料號
                    dr[4] = dtStorage.Rows[i]["LGORT"].ToString().Trim();//入庫倉別
                    dr[5] = dtStorage.Rows[i]["RNDQTY"].ToString();      //卷數
                    dr[6] = dtStorage.Rows[i]["ALQTY"].ToString();       //總需求量
                    dr[7] = "";	 //狀態
                    dtOutTable.Rows.Add(dr);
                }

                ////正式環境
                //string strConnection = GetSAPConnection(this.MANDT);

                //測試環境
                string strConnection = "ASHOST=10.243.23.237 CLIENT=218 SYSNR=07 USER=misec1 PASSWD=77040101";
                string strError = "";
                string strPost = "";

                clsZRFC_INSERT_SMT_DEMANDN.ZDEMANDINNTable dtSAP = new clsZRFC_INSERT_SMT_DEMANDN.ZDEMANDINNTable();
                clsZRFC_INSERT_SMT_DEMANDN.ZRFC_INSERT_SMT_DEMANDN objInsert_SMT_Demadn = new clsZRFC_INSERT_SMT_DEMANDN.ZRFC_INSERT_SMT_DEMANDN();

                dtSAP.FromADODataTable(dtOutTable);
                objInsert_SMT_Demadn.Connection = new SAP.Connector.SAPConnection(strConnection);
                objInsert_SMT_Demadn.Connection.Open();
                try
                {
                    dtReturn = dtOutTable.Clone();
                    objInsert_SMT_Demadn.Zrfc_Insert_Smt_Demandn1(out strPost, ref dtSAP);
                    dtOutTable = dtSAP.ToADODataTable();
                    dtReturn = dtSAP.ToADODataTable();
                    objInsert_SMT_Demadn.Connection.Close();
                }

                catch (Exception ex)
                {
                    ERRMSG = ex.Message + "<- InsertSMTSapInventory()";
                }

                #region
                if (strPost.Trim() != "")
                {
                    //把SAP回傳的狀態加入原始的Table
                    dtStorage.Columns.Add("SAP_RETURN");
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        dtStorage.Rows[i]["SAP_RETURN"] = strPost;
                    }

                }
                else
                {
                    if (strError.Trim() == "")
                        ERRMSG = " SAP Error : Can not post(" + this.MANDT + ")-" + strError.Trim() + "<- InsertSMTSapInventory()";
                    else
                        ERRMSG = " SAP Error : " + this.MANDT + " " + strError + "<- InsertSMTSapInventory()";
                }

                #endregion

                return dtStorage;
            }
            #endregion

