            public bool AddLocationMaintainData(string strLocat, DataTable dtStorage)
            {
                DataWhitm objWhitm = new DataWhitm(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alQueryConditions = new ArrayList();
                ArrayList alUpdateConditions = new ArrayList();
                ArrayList alDeleteConditions = new ArrayList();

                ArrayList arySQL = new ArrayList();
                ArrayList aryLocat = new ArrayList();
                LogData objLogData = new LogData(UserData, WERKS, LGORT, PROGID);
                MixedMaterial objMixed = new MixedMaterial(UserData, WERKS);
                QCI.QWMS.StorageData objStorage = new QCI.QWMS.StorageData(UserData, WERKS, LGORT);

                //WHLOG
                arySQL = objLogData.AddLogData(strLocat, dtStorage);

                //WHITM
                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    if (!objStorage.QueryDataExistsInStorage(strLocat, dtStorage.Rows[i]["MATNR"].ToString(), dtStorage.Rows[i]["INSMK"].ToString(), dtStorage.Rows[i]["OMBLNR"].ToString(), dtStorage.Rows[i]["CHARG"].ToString(), dtStorage.Rows[i]["SERNO"].ToString(), "", ""))
                    {
                        objWhitm.Mandt = UserData.Client;
                        objWhitm.Comcd = UserData.CompanyCode;
                        objWhitm.Werks = dtStorage.Rows[i]["WERKS"].ToString();
                        objWhitm.Lgort = dtStorage.Rows[i]["LGORT"].ToString();
                        objWhitm.Locat = dtStorage.Rows[i]["LOCAT"].ToString();
                        objWhitm.Matnr = dtStorage.Rows[i]["MATNR"].ToString();
                        objWhitm.Insmk = dtStorage.Rows[i]["INSMK"].ToString();
                        objWhitm.Mblnr = dtStorage.Rows[i]["OMBLNR"].ToString();
                        objWhitm.Charg = dtStorage.Rows[i]["CHARG"].ToString();
                        objWhitm.Lifnr = dtStorage.Rows[i]["LIFNR"].ToString();
                        objWhitm.Ebeln = dtStorage.Rows[i]["EBELN"].ToString();
                        objWhitm.Indat = dtStorage.Rows[i]["INDAT"].ToString();
                        objWhitm.Menge = dtStorage.Rows[i]["ALQTY"].ToString();
                        objWhitm.Qcqty = "0";
                        objWhitm.Refno = "";
                        objWhitm.Mrgid = dtStorage.Rows[i]["MRGID"].ToString();
                        objWhitm.Isptm = "";
                        objWhitm.Rmak1 = dtStorage.Rows[i]["RMAK1"].ToString();
                        objWhitm.Crnam = UserData.UserId;
                        objWhitm.Crdat = "getdate()";
                        objWhitm.Monam = UserData.UserId;
                        objWhitm.Modat = "getdate()";
                        objWhitm.Kdmat = dtStorage.Rows[i]["KDMAT"].ToString();
                        objWhitm.Serno = dtStorage.Rows[i]["SERNO"].ToString();
                        objWhitm.Inspt = dtStorage.Rows[i]["INSPT"].ToString();
                        objWhitm.Dacod = dtStorage.Rows[i]["DACOD"].ToString();
                        objWhitm.Locod = dtStorage.Rows[i]["LOCOD"].ToString();
                        objWhitm.Vedat = dtStorage.Rows[i]["VEDAT"].ToString();
                        objWhitm.ExpiryDate = dtStorage.Rows[i]["ExpiryDate"].ToString();


                        arySQL.Add(objWhitm.EntityGetInsertSql());
                    }
                    else
                    {
                        alUpdateConditions.Clear();

                        objWhitm.Menge = dtStorage.Rows[i]["ALQTY"].ToString();
                        objWhitm.Indat = dtStorage.Rows[i]["INDAT"].ToString();
                        objWhitm.Rmak1 = dtStorage.Rows[i]["RMAK1"].ToString();
                        objWhitm.Lifnr = dtStorage.Rows[i]["LIFNR"].ToString();
                        objWhitm.Inspt = dtStorage.Rows[i]["INSPT"].ToString();
                        objWhitm.Dacod = dtStorage.Rows[i]["DACOD"].ToString();
                        objWhitm.Locod = dtStorage.Rows[i]["LOCOD"].ToString();
                        objWhitm.Vedat = dtStorage.Rows[i]["VEDAT"].ToString();
                        objWhitm.Monam = UserData.UserId;
                        objWhitm.Modat = "getdate()";
                        objWhitm.ExpiryDate = dtStorage.Rows[i]["ExpiryDate"].ToString();

                        alUpdateConditions.Add("MANDT = '" + UserData.Client + "'");
                        alUpdateConditions.Add("COMCD = '" + UserData.CompanyCode + "'");
                        alUpdateConditions.Add("WERKS = '" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                        alUpdateConditions.Add("LGORT = '" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                        alUpdateConditions.Add("LOCAT = '" + dtStorage.Rows[i]["LOCAT"].ToString() + "'");
                        alUpdateConditions.Add("MATNR = '" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                        alUpdateConditions.Add("INSMK = '" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
                        alUpdateConditions.Add("MBLNR = '" + dtStorage.Rows[i]["OMBLNR"].ToString() + "'");
                        alUpdateConditions.Add("CHARG = '" + dtStorage.Rows[i]["CHARG"].ToString() + "'");
                        alUpdateConditions.Add("SERNO = '" + dtStorage.Rows[i]["SERNO"].ToString() + "'");

                        arySQL.Add(objWhitm.EntityGetUpdateSql(alUpdateConditions));
                    }
                }

                alDeleteConditions.Add("MANDT = '" + UserData.Client + "'");
                alDeleteConditions.Add("COMCD = '" + UserData.CompanyCode + "'");
                alDeleteConditions.Add("WERKS = '" + WERKS + "'");
                alDeleteConditions.Add("LGORT = '" + LGORT + "'");
                alDeleteConditions.Add("LOCAT = '" + strLocat + "'");
                alDeleteConditions.Add("MENGE = 0");

                arySQL.Add(objWhitm.EntityGetDeleteSql(alDeleteConditions));

                //WHHED
                arySQL.Add("update WHHED set  LOSTS=T.TOTAL from (select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + strLocat + "') as T where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + strLocat + "'");
                //arySQL.Add("update WHHED set  ISMRG=T.ISMRG from (select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + strLocat + "' and MRGID<>'') as T where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + strLocat + "'");

                bool bolReturn = false;
                try
                {
                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return bolReturn;
            }

