            //}

            public DataTable wsUpdateSapInventory_PAL_ByTxt_101(DataTable dtStorage)
            {
                DataTable dtOutTable = new DataTable();
                dtOutTable.TableName = "SAP";
                DataColumnCollection columns = dtOutTable.Columns;
                columns.Add("ZPALLETID", typeof(System.String));   //棧板號
                columns.Add("PLANT", typeof(System.String));       //廠區
                columns.Add("COSTCENTER", typeof(System.String));  //Cost Center
                columns.Add("WO", typeof(System.String));          //工單號
                columns.Add("QTY", typeof(System.Decimal));　　　  //數量
                columns.Add("MATERIAL", typeof(System.String));    //料號
                columns.Add("REGION", typeof(System.String));      //州別，空白
                columns.Add("LOCA", typeof(System.String));        //倉別
                columns.Add("REF1", typeof(System.String));        //版本
                columns.Add("REF2", typeof(System.String));        //操作QWMS人員的工號

                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    DataRow dr = dtOutTable.NewRow();
                    dr[0] = dtStorage.Rows[i]["MBLNR"].ToString().Trim();
                    dr[1] = dtStorage.Rows[i]["WERKS"].ToString().Trim();
                    dr[2] = dtStorage.Rows[i]["KOSTL"].ToString().Trim();
                    dr[3] = dtStorage.Rows[i]["ZEILE"].ToString().Trim();
                    dr[4] = dtStorage.Rows[i]["MENGE"].ToString().Trim();
                    dr[5] = dtStorage.Rows[i]["MATNR"].ToString().Trim();
                    dr[6] = "";
                    dr[7] = dtStorage.Rows[i]["LGORT"].ToString().Trim();
                    dr[8] = dtStorage.Rows[i]["CHARG"].ToString().Trim();
                    dr[9] = "QWMS-" + UserData.UserId.ToString();//記錄操作QWMS人員的工號

                    dtOutTable.Rows.Add(dr);
                }

                string strError = "";
                string strPost = "";
                DataTable dtResponse = new DataTable();
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);

                try
                {
                    int id = objLogData.GenerID_101();
                    string type2 = "";

                    //判斷目前是以ReferenceID or PalletID做入庫動作
                    if (dtStorage.Rows[0]["NMBLN"] != null)
                    {
                        if (!dtStorage.Rows[0]["NMBLN"].ToString().Trim().Equals(""))
                            type2 = "RID";
                        else
                            type2 = "PID";
                    }
                    else
                        type2 = "PID";


                    //產生給SAP扣帳的檔案
                    WriteSapFile_ZRFC_WO_AUTO_GR(dtOutTable);
                    objLogData.OlinePALLogtxt101(dtOutTable, dtResponse, id, "send", type2);

                    //讀取SAP回傳的檔案
                    dtResponse = ReadSapFile_ZRFC_WO_AUTO_GR();

                    objLogData.OlinePALLogtxt101(dtOutTable, dtResponse, id, "return", type2);


                    for (int i = 0; i < dtResponse.Rows.Count; i++)
                    {
                        if (dtResponse.Rows[i]["OMBLN1"] != null)
                        {
                            if (dtResponse.Rows[i]["OMBLN1"].ToString().Trim() != "")
                            {
                                strPost = dtResponse.Rows[i]["OMBLN1"].ToString();
                            }
                        }

                        if (dtResponse.Rows[i]["OMBLN2"] != null)
                        {
                            if (dtResponse.Rows[i]["OMBLN2"].ToString().Trim() != "")
                            {
                                strPost = dtResponse.Rows[i]["OMBLN2"].ToString().Trim();
                            }
                        }

                        if (dtResponse.Rows[i]["ERRMSG"] != null)
                        {
                            //Error Message有回傳值，跳出迴圈
                            strError = dtResponse.Rows[i]["ERRMSG"].ToString().Trim();
                            break;
                        }
                    }

                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    strException = ex.Message;
                    throw new Exception(ex.Message);
                }

                #region 比對SAP回傳的錯誤訊息是否含有扣帳編號，有的話取出扣帳編號

                int MathIndex = 0;
                string strDuplicatDoc = "";
                bool bolTryParse = false;
                long outNumber = 0;
                //strError = "3VPJ7AB5000F3AFD Material Batch is not mapping with WO; Material Document: 5002836760";
                //strError = "3VPJ7AB3000F3AFD Material Batch is not mapping with WO";
                if (strError != "")
                {
                    Regex pattern = new Regex("50");//比對的pattern，SAP回傳的扣帳編號為50開頭
                    Match m = pattern.Match(strError);

                    #region 檢查SAP回傳的扣帳編號是否全為數值型態，避免誤判抓到料號的情況下，誤入了QWMS庫存
                    //【例】SAP回傳的錯誤訊息：3VPJ7AB0000F3AFD Material Batch is not mapping with WO
                    while (m.Success)
                    {
                        MathIndex = m.Index;//取得SAP回傳的扣帳編號之所在的位置
                        bolTryParse = long.TryParse(strError.Substring(MathIndex, 10), out outNumber);

                        if (bolTryParse == false)
                        {
                            strDuplicatDoc = "";
                            m = m.NextMatch();//往下一筆繼續搜尋
                        }
                        else
                        {
                            strDuplicatDoc = outNumber.ToString();//搜尋成功，取出SAP回傳的扣帳編號
                        }

                        if (strDuplicatDoc != "")
                        {
                            break;//搜尋成功，跳出while迴圈不再搜尋
                        }
                    }
                    #endregion
                }

                #endregion

                #region 把扣帳編號加入原始的Table

                if (strPost.Trim() != "")
                {
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        dtStorage.Rows[i]["OMBLNR"] = strPost;
                    }
                }
                else if (strPost.Trim() == "") //strPost等於空值，代表SAP未扣帳成功
                {
                    //SAP已扣帳成功並回傳扣帳編號，但QWMS未扣帳成功
                    if (int.Parse(dtStorage.Rows[0]["OTQTY"].ToString()) == 0 && strDuplicatDoc != "")
                    {
                        for (int i = 0; i < dtStorage.Rows.Count; i++)
                        {
                            dtStorage.Rows[i]["OMBLNR"] = strDuplicatDoc;
                        }

                        strError = "";//清空strError
                    }

                    if (strError.Trim() == "")
                    {
                        if (strException != "")
                        {
                            ERRMSG = " SAP Error : Can not post(" + this.MANDT + ")-" + strError.Trim() + "<- wsUpdateSapInventory_PAL_ByTXT()";
                        }
                    }
                    else
                    {
                        ERRMSG = " SAP Error : " + this.MANDT + " " + strError + "<- wsUpdateSapInventory_PAL_ByTXT()";
                    }
                }

                #endregion

                return dtStorage;
            }

            #endregion

