                    //arySQL.Add(sbSql.ToString());
                }
                #endregion


                #region 更新入库状态IOFLAGE=Y---入库
                sbSql.Remove(0, sbSql.Length);
                //HAC
                //sbSql.AppendFormat(" UPDATE WHDWN SET IOFLAGE='Y' WHERE MBLNR='{0}' AND MTYPE IN ('QMS','QMS_311') ", dtStorage.Rows[0]["MBLNR"].ToString());
                sbSql.AppendFormat(" UPDATE WHDWN SET IOFLAGE='Y' , OTQTY = MENGE WHERE MANDT ='218'AND MTYPE IN ('QMS','QMS_311') AND MBLNR='{0}'  AND COMCD='{1}'", dtStorage.Rows[0]["MBLNR"].ToString(), COMCD);
                arySQL.Add(sbSql.ToString());

                #endregion

                #region whbox



                //HAC
                StringBuilder strsqlbox = new StringBuilder();
                strsqlbox.AppendFormat(" INSERT INTO WHBOX (MANDT,COMCD,WERKS,LGORT,LOCAT,MBLNR,BOXID,INSMK,CHARG,MATNR,SERNO,LOADID,KDMAT,MENGE,CRTDAT) ");
                strsqlbox.AppendFormat(" SELECT MANDT,COMCD,WERKS,LGORT,'" + dtStorage.Rows[0]["LOCAT"].ToString() + "' as LOCAT,MBLNR,BOXID,INSMK,CHARG,MATNR,SERNO,LOADID,KDMAT,MENGE,GETDATE() ");
                //strsqlbox.AppendFormat(" FROM WHDWN WITH (NOLOCK) WHERE MANDT ='218' AND MTYPE IN ('QMS','QMS_311') AND SUBSTRING(MATNR,1,4) IN('20JH','2LJH') AND  MBLNR='" + dtStorage.Rows[0]["MBLNR"].ToString() + "'");
                strsqlbox.AppendFormat(" FROM WHDWN WITH (NOLOCK) WHERE MANDT ='218' AND MTYPE IN ('QMS','QMS_311') AND  MBLNR='" + dtStorage.Rows[0]["MBLNR"].ToString() + "'");
                arySQL.Add(strsqlbox.ToString());

                #endregion

                bool bolReturn = false;
                try
                {
                    //拿掉防呆限制，前端刷S/N時，若OTQTY=0時，根本帶不出資料，所以不需要再檢查  Smose Liao 20141002
                    #region 防呆，避免重複處理同一張SAP Document(Deleted)
