                    objWhdwn.ResetField();
                    objWhdwn.Ombln = dtStorage.Rows[i]["OMBLNR"].ToString();
                    objWhdwn.Otqty = "OTQTY +" + dtStorage.Rows[i]["ALQTY"].ToString();
                    alConditions.Add("Mandt='" + MANDT + "'");
                    alConditions.Add("Comcd='" + COMCD + "'");
                    //alConditions.Add("Mblnr='" + dtStorage.Rows[i]["NMBLN"].ToString() + "'");
                    alConditions.Add("Mblnr='" + dtStorage.Rows[i]["MBLNR"].ToString() + "'");
                    alConditions.Add("Zeile='" + dtStorage.Rows[i]["ZEILE"].ToString() + "'");
                    if (dtStorage.Columns.Contains("BOXID"))
                    {
                        if (!string.IsNullOrEmpty(dtStorage.Rows[i]["BOXID"].ToString()))
                        {
                            if (dtStorage.Rows[i]["BOXID"].ToString() != "")
                            {
                                alConditions.Add("BOXID='" + dtStorage.Rows[i]["BOXID"].ToString() + "'");
                            }
                        }
                    }
                    alConditions.Add("MTYPE='QMS_M'");
                    strTemp = "";
                    strTemp = objWhdwn.EntityGetUpdateSql(alConditions);
                    arySQL.Add(strTemp);

                    alColumns.Clear();
                    alConditions.Clear();
                    objWhdwn.ResetField();
                    alColumns.Add(" MBLNR + '--' + ZEILE ");
                    alConditions.Add("(MANDT= '" + MANDT + "')");
                    alConditions.Add("(COMCD= '" + COMCD + "')");
                    //alConditions.Add("(MBLNR= '" + dtStorage.Rows[i]["NMBLN"].ToString() + "')");
                    alConditions.Add("(MBLNR= '" + dtStorage.Rows[i]["MBLNR"].ToString() + "')");
                    alConditions.Add("(ZEILE= '" + dtStorage.Rows[i]["ZEILE"].ToString() + "')");
                    if (dtStorage.Columns.Contains("BOXID"))
                    {
                        if (!string.IsNullOrEmpty(dtStorage.Rows[i]["BOXID"].ToString()))
                        {
                            if (dtStorage.Rows[i]["BOXID"].ToString() != "")
                            {
                                alConditions.Add("BOXID='" + dtStorage.Rows[i]["BOXID"].ToString() + "'");
                            }
                        }
                    }
                    alConditions.Add("(MTYPE='QMS_M')");
                    alConditions.Add("(MENGE=OTQTY)");
                    alConditions.Add("(OTQTY = '" + dtStorage.Rows[i]["ALQTY"].ToString() + "')");
                    strTemp = "";
                    strTemp = objWhdwn.EntityGetQuerySql(alColumns, alConditions, false, true);
                    aryCheckSQL.Add(strTemp);
                    #endregion
                }

                #region "Update WHHED Table"
                for (int i = 0; i < aryLocat.Count; i++)
                {

                    sbSql.Append("Update WHHED set  ");
                    sbSql.AppendFormat("  LOSTS=T.TOTAL from ");
                    sbSql.AppendFormat(" (Select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "') as T  ");
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocat[i].ToString());
                    arySQL.Add(sbSql.ToString());

                    //sbSql.Remove(0, sbSql.Length);
                    //sbSql.Append("Update WHHED set  ");
                    //sbSql.AppendFormat("  ISMRG=T.ISMRG from ");
                    //sbSql.AppendFormat(" (Select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "' and MRGID<>'') as T  ");
                    //sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    //sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    //sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    //sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    //sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocat[i].ToString());
                    //arySQL.Add(sbSql.ToString());
                    //arySQL.Add("update WHHED set  LOSTS=T.TOTAL from (select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm where MANDT= '" + MANDT + "' and COMCD='"+COMCD+"'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "') as T where MANDT= '" + MANDT + "' and COMCD='"+COMCD+"' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "'");
                    //arySQL.Add("update WHHED set  ISMRG=T.ISMRG from (select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "' and MRGID<>'') as T where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "'");
                }
                #endregion



                bool bolReturn = false;
                try
                {
                    #region 防呆，避免重複處理同一張SAP Document
                    DataTable dtChkTmp;

                    for (int j = 0; j < aryCheckSQL.Count; j++)
                    {
                        //dtChkTmp = objSQLAccess.GetDataTable(aryCheckSQL[j].ToString());
                        ControlHandleDB();
                        dtChkTmp = ControlSqlAccess.GetDataTable(aryCheckSQL[j].ToString());
                        ControlSqlAccess.CloseConnection();

                        if (dtChkTmp.Rows.Count > 0)
                            aryCheckList.Add(dtChkTmp.Rows[0][0].ToString());
                    }

                    #endregion

                    if (aryCheckList.Count > 0)
                    {
                        #region 防呆，避免重複處理同一張SAP Document

                        sbCheckList.Remove(0, sbCheckList.Length);
                        for (int j = 0; j < aryCheckList.Count; j++)
                        {
                            if (j != 0)
                                sbCheckList.Append(" , ");
                            sbCheckList.Append(aryCheckList[j]);
                        }
                        ERRMSG = "Doc. No. " + sbCheckList.ToString() + " are processed. Please Check it.";
                        #endregion
                    }
                    else
                    {
                        ControlHandleDB();
                        bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                        ControlSqlAccess.CloseConnection();
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return bolReturn;
            }

