            # region 增加并储资料 add by Mandy
            /// <summary>
            /// 增加并储资料
            /// </summary> 
            /// <param name="strLocat">旧储位</param>
            /// <param name="strNewLocat">新储位</param>
            /// <param name="dtStorage">要调整的资料Table</param>
            /// <returns>
            /// bool
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(UserData,strWerks,strLgort,strMblnr,strProgid);
            ///  bool  bolReturn = objStorageIn.AddLocationCombineData(strLocat,strNewLocat,dtStorage);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////	
            public bool AddLocationCombineData(string strLocat, string strNewLocat, DataTable dtStorage)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddLocationCombineData";
                this.ControlMethodParm = "('" + strLocat + "','" + strNewLocat + "','" + dtStorage + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    ArrayList arySQL = new ArrayList();
                    ArrayList aryLocat = new ArrayList();
                    LogData objLogData = new LogData(UserData, WERKS, LGORT, PROGID);
                    MixedMaterial objMixed = new MixedMaterial(UserData, WERKS);
                    StorageData objStorage = new StorageData(UserData, WERKS, LGORT);
                    DataWhitm objDataWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    DataWhbox objDataWhbox = new DataWhbox(UserData);
                    string strSQL;
                    string Config;
                    //WHLOG
                    arySQL = objLogData.AddLogData(strLocat, strNewLocat, dtStorage);
               
                    //WHITM
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        if (dtStorage.Columns.Contains("CONFIG") && !string.IsNullOrEmpty(dtStorage.Rows[i]["CONFIG"].ToString()))
                        {
                            Config = dtStorage.Rows[i]["CONFIG"].ToString();
                        }
                        else
                        {
                            Config = "";
                        }
                        if (!objStorage.QueryDataExistsInStorageLC(strNewLocat, dtStorage.Rows[i]["MATNR"].ToString(), dtStorage.Rows[i]["INSMK"].ToString(), dtStorage.Rows[i]["OMBLNR"].ToString(), dtStorage.Rows[i]["CHARG"].ToString(), dtStorage.Rows[i]["SERNO"].ToString(), dtStorage.Rows[i]["DACOD"].ToString(), dtStorage.Rows[i]["LOCOD"].ToString(), Config))
                        {
                            #region 新储位中，不存在该料号库存的情况

                            #region  INSERT  WHITM   改回舊的strSQL寫法，Create Date才不會被objDataWhitm.EntityGetInsertSql()改成當天日期  Smose Liao 20100601

                            strSQL = "Insert into WHITM(MANDT, COMCD, WERKS, LGORT, LOCAT, MATNR, INSMK, MBLNR, CHARG, LIFNR, EBELN, INDAT, VEDAT, MENGE, "
                            + "  QCQTY, REFNO, MRGID, ISPTM, RMAK1, CRNAM, CRDAT, KDMAT, MONAM, MODAT, SERNO, BOXID, DACOD, LOCOD, INSPT, RMANO, PKDAT,ExpiryDate,TASKID,MAXEXP,LOCKED,CONFIG)  values "
                            + "('" + dtStorage.Rows[i]["MANDT"].ToString() + "', '" + dtStorage.Rows[i]["COMCD"].ToString() + "', '" + dtStorage.Rows[i]["WERKS"].ToString() + "', "
                            + " '" + dtStorage.Rows[i]["LGORT"].ToString() + "',  '" + strNewLocat + "'  ,'" + dtStorage.Rows[i]["MATNR"].ToString() + "','" + dtStorage.Rows[i]["INSMK"].ToString() + "', "
                            + " '" + dtStorage.Rows[i]["OMBLNR"].ToString() + "','" + dtStorage.Rows[i]["CHARG"].ToString() + "','" + dtStorage.Rows[i]["LIFNR"].ToString() + "',"
                            + " '" + dtStorage.Rows[i]["EBELN"].ToString() + "','" + dtStorage.Rows[i]["INDAT"].ToString() + "','" + dtStorage.Rows[i]["VEDAT"].ToString() + "',"
                            + dtStorage.Rows[i]["ALQTY"].ToString() + ", 0, '', '', '','" + dtStorage.Rows[i]["RMAK1"].ToString() + "','" + CRNAM + "','" + dtStorage.Rows[i]["CRDAT"].ToString() + "', "
                            + " '" + dtStorage.Rows[i]["KDMAT"].ToString() + "','" + CRNAM + "', getdate(),'" + dtStorage.Rows[i]["SERNO"].ToString() + "','" + dtStorage.Rows[i]["BOXID"].ToString() + "',"
                            + "  '" + dtStorage.Rows[i]["DACOD"].ToString() + "','" + dtStorage.Rows[i]["LOCOD"].ToString() + "','" + dtStorage.Rows[i]["INSPT"].ToString() + "',"
                            +" '" + dtStorage.Rows[i]["RMANO"].ToString() + "','" + dtStorage.Rows[i]["PKDAT"].ToString() + "','" + dtStorage.Rows[i]["ExpiryDate"].ToString() + "','" + dtStorage.Rows[i]["TASKID"].ToString() + "','" + dtStorage.Rows[i]["MAXEXP"].ToString() + "','" + dtStorage.Rows[i]["LOCKED"].ToString() + "','"+ Config+"')";

                            arySQL.Add(strSQL);
                            #endregion


                            if (dtStorage.Rows[i]["MENGE"].ToString() == dtStorage.Rows[i]["ALQTY"].ToString())
                            {
                                #region DELETE WHITM 转储的库存足够，删除原库存
                                alConditions.Clear();
                                alConditions.Add("MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                                alConditions.Add("COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                                alConditions.Add("WERKS='" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                                alConditions.Add("LGORT='" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                                alConditions.Add("LOCAT='" + strLocat + "'");
                                alConditions.Add("MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                                alConditions.Add("INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
                                alConditions.Add("MBLNR='" + dtStorage.Rows[i]["OMBLNR"].ToString() + "'");
                                alConditions.Add("CHARG='" + dtStorage.Rows[i]["CHARG"].ToString() + "'");
                                alConditions.Add("SERNO='" + dtStorage.Rows[i]["SERNO"].ToString() + "'");
                                alConditions.Add("BOXID='" + dtStorage.Rows[i]["BOXID"].ToString() + "'");
                                alConditions.Add("DACOD='" + dtStorage.Rows[i]["DACOD"].ToString() + "'");
                                alConditions.Add("LOCOD='" + dtStorage.Rows[i]["LOCOD"].ToString() + "'");
                                arySQL.Add(objDataWhitm.EntityGetDeleteSql(alConditions));
                                #endregion
                            }
                            else
                            {
                                #region UPDATE WHITM 转储库存多余的情况
                                objDataWhitm.ResetField();
                                objDataWhitm.Menge = "MENGE-" + dtStorage.Rows[i]["ALQTY"].ToString();

                                alConditions.Clear();
                                alConditions.Add("MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                                alConditions.Add("COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                                alConditions.Add("WERKS='" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                                alConditions.Add("LGORT='" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                                alConditions.Add("LOCAT='" + strLocat + "'");
                                alConditions.Add("MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                                alConditions.Add("INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
                                alConditions.Add("MBLNR='" + dtStorage.Rows[i]["OMBLNR"].ToString() + "'");
                                alConditions.Add("CHARG='" + dtStorage.Rows[i]["CHARG"].ToString() + "'");
                                alConditions.Add("SERNO='" + dtStorage.Rows[i]["SERNO"].ToString() + "'");
                                alConditions.Add("BOXID='" + dtStorage.Rows[i]["BOXID"].ToString() + "'");
                                alConditions.Add("DACOD='" + dtStorage.Rows[i]["DACOD"].ToString() + "'");
                                alConditions.Add("LOCOD='" + dtStorage.Rows[i]["LOCOD"].ToString() + "'");
                                arySQL.Add(objDataWhitm.EntityGetUpdateSql(alConditions));
                                #endregion
                            }

                            #endregion
                        }
                        else
                        {
                            #region 新储位中，已有该料号
                            #region 比較新舊儲位的棧板滿板時間，以最新的時間為主  Smose Liao 20130326
                            string strOldPkdat = "";
                            string strNewPkdat = "";
                            strOldPkdat = dtStorage.Rows[0]["PKDAT"].ToString().Trim();
                            DataTable dtNewLocat = objStorage.QueryStorageDetailData(strNewLocat, "N");
                            if (dtNewLocat.Rows.Count > 0)
                                strNewPkdat = dtNewLocat.Rows[0]["PKDAT"].ToString().Trim();
                            if (strNewPkdat != "" && strOldPkdat != "")//新舊儲位的棧板滿板時間不為空才做比較日期的動作，否則會出現Exception
                            {
                                if (DateTime.Parse(strNewPkdat) < DateTime.Parse(strOldPkdat)) //舊儲位的滿板時間比新儲位的滿板時間還新
                                    strNewPkdat = strOldPkdat;
                            }
                            #endregion

                            #region UPDATE WHITM
                            objDataWhitm.ResetField();
                            objDataWhitm.Pkdat = strNewPkdat;
                            objDataWhitm.Menge = "MENGE +" + dtStorage.Rows[i]["ALQTY"].ToString();
                            objDataWhitm.Qcqty = "QCQTY + " + dtStorage.Rows[i]["QCQTY"].ToString();
                            objDataWhitm.Monam = CRNAM;
                            objDataWhitm.Modat = "getdate()";

                            alConditions.Clear();
                            alConditions.Add("MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                            alConditions.Add("COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                            alConditions.Add("WERKS='" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                            alConditions.Add("LGORT='" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                            alConditions.Add("LOCAT='" + strNewLocat + "'");
