            public bool AddLocationCombineDataCSMC(string strLocat, string strNewLocat, DataTable dtStorage, DataTable dtWhbox, string strLgortOld, string strLogortNew)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddLocationCombineData";
                this.ControlMethodParm = "('" + strLocat + "','" + strNewLocat + "','" + dtStorage + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    ArrayList arySQL = new ArrayList();
                    ArrayList aryLocat = new ArrayList();
                    LogData objLogData = new LogData(UserData, WERKS, LGORT, PROGID);
                    MixedMaterial objMixed = new MixedMaterial(UserData, WERKS);
                    StorageData objStorage = new StorageData(UserData, WERKS, LGORT);
                    DataWhitm objDataWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    DataWhbox objDataWhbox = new DataWhbox(UserData);
                    string strSQL;

                    #region WHLOG
                    arySQL = objLogData.AddLogData(strLocat, strNewLocat, dtStorage);

                    #endregion

                    DataTable dtwhboxtmp = new DataTable();
                    if (dtWhbox != null)
                    {
                        if (dtWhbox.Rows.Count > 0)
                        {
                            dtwhboxtmp = dtWhbox.Copy();
                        }
                        else
                        {
                            dtwhboxtmp = null;
                        }
                    }
                    else
                    {
                        dtwhboxtmp = null;
                    }

                    #region WHITM
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        if (!objStorage.QueryDataExistsInStorage(strNewLocat, dtStorage.Rows[i]["MATNR"].ToString(), dtStorage.Rows[i]["INSMK"].ToString(), dtStorage.Rows[i]["OMBLNR"].ToString(), dtStorage.Rows[i]["CHARG"].ToString(), dtStorage.Rows[i]["SERNO"].ToString(), "", ""))
                        {
                            #region 无库存部分

                            #region WHITM

                            strSQL = "Insert into WHITM(MANDT, COMCD, WERKS, LGORT, LOCAT, MATNR, INSMK, MBLNR, CHARG, LIFNR, EBELN, INDAT, VEDAT, MENGE, QCQTY, REFNO, MRGID, ISPTM, RMAK1, CRNAM, CRDAT, KDMAT, MONAM, MODAT, SERNO, BOXID, DACOD, LOCOD, INSPT, RMANO, PKDAT) " +
                                "values('" + dtStorage.Rows[i]["MANDT"].ToString() + "', '" + dtStorage.Rows[i]["COMCD"].ToString() + "', '" + dtStorage.Rows[i]["WERKS"].ToString() + "','" + strLogortNew + "','" +
                                strNewLocat + "','" + dtStorage.Rows[i]["MATNR"].ToString() + "','" + dtStorage.Rows[i]["INSMK"].ToString() + "','" + dtStorage.Rows[i]["OMBLNR"].ToString() + "','" +
                                dtStorage.Rows[i]["CHARG"].ToString() + "','" + dtStorage.Rows[i]["LIFNR"].ToString() + "','" + dtStorage.Rows[i]["EBELN"].ToString() + "','" + dtStorage.Rows[i]["INDAT"].ToString() + "','" + dtStorage.Rows[i]["VEDAT"].ToString() + "'," +
                                dtStorage.Rows[i]["ALQTY"].ToString() + ", 0, '', '', '','" + dtStorage.Rows[i]["RMAK1"].ToString() + "','" + CRNAM + "','" + dtStorage.Rows[i]["CRDAT"].ToString() + "','" + dtStorage.Rows[i]["KDMAT"].ToString() + "','" + CRNAM + "', getdate(),'" +
                                dtStorage.Rows[i]["SERNO"].ToString() + "','" + dtStorage.Rows[i]["BOXID"].ToString() + "','" + dtStorage.Rows[i]["DACOD"].ToString() + "','" + dtStorage.Rows[i]["LOCOD"].ToString() + "','" + dtStorage.Rows[i]["INSPT"].ToString() + "','" + dtStorage.Rows[i]["RMANO"].ToString() + "','" + dtStorage.Rows[i]["PKDAT"].ToString() + "')";


                            arySQL.Add(strSQL);
                            #endregion

                            #region 查询库存
                            if (dtwhboxtmp == null)
                            {
                                dtWhbox = Querywhbox(dtStorage.Rows[i]["WERKS"].ToString(), strLgortOld, strLocat, dtStorage.Rows[i]["OMBLNR"].ToString(), "", dtStorage.Rows[i]["INSMK"].ToString(), dtStorage.Rows[i]["CHARG"].ToString(),
                                          dtStorage.Rows[i]["MATNR"].ToString(), "");
                            }
                            #endregion

                            #region WHITM WHBOX
                            if (dtStorage.Rows[i]["MENGE"].ToString() == dtStorage.Rows[i]["ALQTY"].ToString())
                            {
                                #region 全部并储
                                alConditions.Clear();
                                alConditions.Add("MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                                alConditions.Add("COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                                alConditions.Add("WERKS='" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                                alConditions.Add("LGORT='" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                                alConditions.Add("LOCAT='" + strLocat + "'");
                                alConditions.Add("MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                                alConditions.Add("INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
                                alConditions.Add("MBLNR='" + dtStorage.Rows[i]["OMBLNR"].ToString() + "'");
                                alConditions.Add("CHARG='" + dtStorage.Rows[i]["CHARG"].ToString() + "'");
                                alConditions.Add("SERNO='" + dtStorage.Rows[i]["SERNO"].ToString() + "'");
                                alConditions.Add("BOXID='" + dtStorage.Rows[i]["BOXID"].ToString() + "'");
                                alConditions.Add("DACOD='" + dtStorage.Rows[i]["DACOD"].ToString() + "'");
                                alConditions.Add("LOCOD='" + dtStorage.Rows[i]["LOCOD"].ToString() + "'");
                                arySQL.Add(objDataWhitm.EntityGetDeleteSql(alConditions));

                                objDataWhbox.ResetField();
                                objDataWhbox.Locat = strNewLocat;
                                objDataWhbox.Lgort = strLogortNew;
                                alConditions.Clear();
                                alConditions.Clear();
                                alConditions.Add("MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                                alConditions.Add("COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                                alConditions.Add("WERKS='" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                                alConditions.Add("LGORT='" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                                alConditions.Add("LOCAT='" + strLocat + "'");
                                alConditions.Add("MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                                alConditions.Add("INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
