                                alConditions.Add("MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                                alConditions.Add("INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
                                alConditions.Add("MBLNR='" + dtStorage.Rows[i]["OMBLNR"].ToString() + "'");
                                alConditions.Add("CHARG='" + dtStorage.Rows[i]["CHARG"].ToString() + "'");
                                alConditions.Add("SERNO='" + dtStorage.Rows[i]["SERNO"].ToString() + "'");
                                alConditions.Add("BOXID='" + dtStorage.Rows[i]["BOXID"].ToString() + "'");
                                alConditions.Add("DACOD='" + dtStorage.Rows[i]["DACOD"].ToString() + "'");
                                alConditions.Add("LOCOD='" + dtStorage.Rows[i]["LOCOD"].ToString() + "'");
                                arySQL.Add(objDataWhitm.EntityGetUpdateSql(alConditions));

                                if (dtWhbox.Rows.Count > 0)
                                {

                                    for (int k = 0; k < dtWhbox.Rows.Count; k++)
                                    {
                                        objDataWhbox.ResetField();
                                        objDataWhbox.Locat = strNewLocat;
                                        objDataWhbox.Lgort = strLogortNew;
                                        alConditions.Clear();
                                        alConditions.Clear();
                                        alConditions.Add("MANDT='" + dtWhbox.Rows[k]["MANDT"].ToString() + "'");
                                        alConditions.Add("COMCD='" + dtWhbox.Rows[k]["COMCD"].ToString() + "'");
                                        alConditions.Add("WERKS='" + dtWhbox.Rows[k]["WERKS"].ToString() + "'");
                                        alConditions.Add("LGORT='" + dtWhbox.Rows[k]["LGORT"].ToString() + "'");
                                        alConditions.Add("LOCAT='" + strLocat + "'");
                                        alConditions.Add("MATNR='" + dtWhbox.Rows[k]["MATNR"].ToString() + "'");
                                        alConditions.Add("INSMK='" + dtWhbox.Rows[k]["INSMK"].ToString() + "'");
                                        alConditions.Add("MBLNR='" + dtWhbox.Rows[k]["MBLNR"].ToString() + "'");
                                        alConditions.Add("CHARG='" + dtWhbox.Rows[k]["CHARG"].ToString() + "'");
