                                        alConditions.Add("BOXID='" + dtWhbox.Rows[k]["BOXID"].ToString() + "'");


                                        arySQL.Add(objDataWhbox.EntityGetUpdateSql(alConditions));
                                    }


                                }
                                #endregion
                            }
                            #endregion

                            #endregion

                        }
                        else
                        {
                            #region 有库存部分
                            string strOldPkdat = "";
                            string strNewPkdat = "";
                            strOldPkdat = dtStorage.Rows[0]["PKDAT"].ToString().Trim();
                            DataTable dtNewLocat = objStorage.QueryStorageDetailData(strNewLocat, "N");
