            #region 318自動轉倉

            #region Call SAP 作轉倉動作
            //===================================================================================
            ////////////Summary by Smose Liao 20091106///////////////////////////////////////////
            /// <summary>
            /// Call SAP 作轉倉動作
            /// </summary> 
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  DataTable dtReturn = objStorageIn.UpdateSapTransfer(dtStorage);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            ////////////////////////////////////////////////////////////////////////////////////   
            public DataTable UpdateSapTransfer(DataTable dtStorage)
            {
                DataTable dtOutTable = new DataTable();
                dtOutTable.TableName = "Return";
                DataColumnCollection columns = dtOutTable.Columns;
                columns.Add("REFNO", typeof(System.String));   //Reference No. 放QWMS UserID
                columns.Add("PLANT", typeof(System.String));   //廠區
                columns.Add("MATNR", typeof(System.String));   //料號
                columns.Add("KOSTL", typeof(System.String));   //Cost Center
                columns.Add("LGORTF", typeof(System.String));  //發料倉別
                columns.Add("LGORTT", typeof(System.String));  //入庫倉別
                columns.Add("RETQTY", typeof(System.Decimal)); //Qty
                columns.Add("STATUS", typeof(System.String));  //狀態


                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    DataRow dr = dtOutTable.NewRow();
                    dr[0] = this.CRNAM.Trim();//Reference No. 放QWMS UserID					 
                    dr[1] = dtStorage.Rows[i]["WERKS"].ToString().Trim();//廠區
                    dr[2] = dtStorage.Rows[i]["MATNR"].ToString().Trim();//料號
                    dr[3] = "";//Cost Center
                    dr[4] = dtStorage.Rows[i]["LGORT_FROM"].ToString().Trim();//發料倉別
                    dr[5] = dtStorage.Rows[i]["LGORT_TO"].ToString().Trim();//入庫倉別
                    dr[6] = dtStorage.Rows[i]["MENGE"].ToString().Trim(); //Qty
                    dr[7] = "";	 //狀態
                    dtOutTable.Rows.Add(dr);
                }

                string strConnection = GetSAPConnection(this.MANDT);
                string strError = "";
                string strPost = "";
                string strFlag = "";

                //Z_RFC_QMS_AUTO_RETURN_318.Z_RFC_QMS_AUTO_RETURN_318 

                #region 318 轉倉

                Z_RFC_QMS_AUTO_RETURN_318.SAPProxy objSAPProxy = new Z_RFC_QMS_AUTO_RETURN_318.SAPProxy();
                Z_RFC_QMS_AUTO_RETURN_318.ZRTOSAPTable dtSAP = new Z_RFC_QMS_AUTO_RETURN_318.ZRTOSAPTable();
                dtSAP.FromADODataTable(dtOutTable);


                objSAPProxy.Connection = new SAP.Connector.SAPConnection(strConnection);
                objSAPProxy.Connection.Open();
                #endregion

                #region SMT原程式
                //				SAP311_RETURN.SAP311_RETURN objSAPProxy = new SAP311_RETURN.SAP311_RETURN();
                //				SAP311_RETURN.ZRTOSAPTable dtSAP = new SAP311_RETURN.ZRTOSAPTable();
                //				dtSAP.FromADODataTable(dtOutTable);
                //				objSAPProxy.Connection = new SAP.Connector.SAPConnection(strConnection);
                //				objSAPProxy.Connection.Open();
                #endregion

                try
                {
                    objSAPProxy.Z_Rfc_Qms_Auto_Return_318(out strError, out strFlag, out strPost, ref dtSAP);
                    dtOutTable = dtSAP.ToADODataTable();
                    objSAPProxy.Connection.Close();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }


                if (strPost.Trim() != "")
                {
                    //把扣帳編號加入原始的Table
                    //dtStorage.Columns.Add("MBLNR");
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        dtStorage.Rows[i]["MBLNR"] = strPost;
                    }

                }
                else
                {
                    if (strError.Trim() == "")
                    {
                        ERRMSG = " SAP Error : Can not post(" + this.MANDT + ")-" + strError.Trim() + "<- UpdateSapTransfer()";
                    }
                    else
                    {
                        ERRMSG = " SAP Error : " + this.MANDT + " " + strError + "<- UpdateSapTransfer()";
                    }
                }

                return dtStorage;
            }


            #endregion

            #region  查詢318的SAP庫存
            //====================================================================================
            ////////////Summary by Smose Liao 20091106////////////////////////////////////////////
            /// <summary>
            /// 查詢318的SAP庫存 
            /// </summary> 
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  DataTable dtReturn = objStorageIn.QuerySap318Inventory(dtStorage);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////   
            public DataTable QuerySap318Inventory(DataTable dtStorage)
            {
                DataTable dtOutTable = new DataTable();
                dtOutTable.TableName = "QMS";
                DataColumnCollection columns = dtOutTable.Columns;
                columns.Add("PLANT", typeof(System.String));         //廠區
                columns.Add("LOCATION", typeof(System.String));      //倉別
                columns.Add("MATERIAL", typeof(System.String));      //料號
                columns.Add("STOCK", typeof(System.Decimal));　　　　//庫存
                columns.Add("ROUNDING", typeof(System.Decimal));     //最小包裝量
                columns.Add("STATUS", typeof(System.String));

                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    DataRow dr = dtOutTable.NewRow();
                    dr[0] = dtStorage.Rows[i]["WERKS"].ToString().Trim();
                    dr[1] = dtStorage.Rows[i]["LGORT_FROM"].ToString().Trim();
                    dr[2] = dtStorage.Rows[i]["MATNR"].ToString().Trim();
                    dr[3] = 0;
                    dr[4] = 0;
                    dr[5] = "";
                    dtOutTable.Rows.Add(dr);
                }

                string strConnection = GetSAPConnection(this.MANDT);
                string strFlag = "";

                #region 318轉倉



                Z_RFC_QMS_STOCK_318.SAPProxy objSAPProxy = new Z_RFC_QMS_STOCK_318.SAPProxy();
                Z_RFC_QMS_STOCK_318.ZSTOCKROUNTable dtSAP = new Z_RFC_QMS_STOCK_318.ZSTOCKROUNTable();
                dtSAP.FromADODataTable(dtOutTable);
                objSAPProxy.Connection = new SAP.Connector.SAPConnection(strConnection);
                objSAPProxy.Connection.Open();

                try
                {
                    objSAPProxy.Z_Rfc_Qms_Stock_3x8(out strFlag, ref dtSAP);
                    dtOutTable = dtSAP.ToADODataTable();
                    objSAPProxy.Connection.Close();

                    //把SAP Qty加入原始的Table
                    if (dtStorage.Columns.IndexOf("SAPQY") < 0)
                        dtStorage.Columns.Add("SAPQY", typeof(System.Decimal));

                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {

                        DataRow[] drFound = dtOutTable.Select("MATERIAL='" + dtStorage.Rows[i]["MATNR"].ToString().Trim() + "'");
                        if (drFound.Length > 0)
                        {
                            dtStorage.Rows[i]["SAPQY"] = drFound[0]["STOCK"];
                        }
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                #endregion



                if (strFlag.ToUpper().Trim() == "Y")
                {
                    return dtStorage;
                }
                else
                {
                    ERRMSG = " Can not connection to SAP-" + this.MANDT + "<- QuerySapInventory()";
                }
                return dtOutTable;
            }


