                        if (!objStorageData.QueryDataExistsInStorage(dtStorage.Rows[i]["LOCAT"].ToString(), dtStorage.Rows[i]["MATNR"].ToString(), dtStorage.Rows[i]["INSMK"].ToString(), dtStorage.Rows[i]["MBLNR"].ToString(), dtStorage.Rows[i]["CHARG"].ToString()))
                        {
                            //strSQL = "Insert into WHITM(MANDT, WERKS, LGORT, LOCAT, MATNR, INSMK, MBLNR, CHARG, LIFNR, EBELN, INDAT, MENGE, QCQTY, REFNO, MRGID, ISPTM, RMAK1,CRNAM, CRDAT, MONAM, MODAT) " +
