                            //    "' and LGORT= '" + dtStorage.Rows[i]["Lgort_To"].ToString() + "' and LOCAT= '" + dtStorage.Rows[i]["LOCAT_To"].ToString() + "' and MATNR= '" + dtStorage.Rows[i]["MATNR"].ToString() + "' and INSMK='" + dtStorage.Rows[i]["INSMK"].ToString() +
                            //    "' and MBLNR= '" + dtStorage.Rows[i]["MBLNR"].ToString() + "' and CHARG= '" + dtStorage.Rows[i]["CHARG"].ToString() + "'";
                            objWhitm.Menge = "MENGE - " + dtStorage.Rows[i]["ALQTY"].ToString();
                            objWhitm.Rmak1 = dtStorage.Rows[i]["RMAK1"].ToString();
