                    }

                    //WHHED
                    #region "Update WHHED Table"
                    for (int i = 0; i < aryLocat.Count; i++)
                    {
                        arySQL.Add("update WHHED set  LOSTS=T.TOTAL from (select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "') as T where MANDT= '" + MANDT + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "'");
                        //arySQL.Add("update WHHED set  ISMRG=T.ISMRG from (select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "' and MRGID<>'') as T where MANDT= '" + MANDT + "' and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "'");
                    }
                    #endregion

                    alReturn = arySQL;
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
