            ////////////Summary by Ryan Tsai 20111023////////////////////////////////////////////
            /// <summary>
            /// 檢驗入出庫
            /// </summary> 
            /// <param name="">FROM庫存資料</param>
            /// <param name="">TO庫存資料</param>
            /// <param name="">檢驗入/出庫</param>
            /// <returns>
            /// bool。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  bool  bolReturn = objStorageIn.AddProdOnLineInData(dtIQCStorage,dtWHStorage);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            //////////////////////////////////////////////////////////////////////////////////////	
            public bool AddIQCIndata(DataTable dtToStorage, DataTable dtFromStorage, string strFlag)
            {
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);
                DataWhhed objWhhed = new DataWhhed(UserData);
                DataWhecd objWhecd = new DataWhecd(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                StringBuilder sbSql = new StringBuilder();

                ArrayList arySQL = new ArrayList();

                ArrayList aryCheckSQL = new ArrayList();
                string strSQL;
                //紀錄異動儲位
                ArrayList aryLocatTo = new ArrayList();
                ArrayList aryLgortTo = new ArrayList();

                string strTempLocatTo = "";
                ArrayList aryLocatFrom = new ArrayList();
                string strTempLocatFrom = "";


                #region 紀錄Log
                //WHLOG
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);
                arySQL = objLogData.AddLogData("", "StorageOut", dtFromStorage);  //轉出庫存紀錄
                arySQL.Add(objLogData.AddLogData("", "StorageIn", dtToStorage)[0].ToString()); //轉入庫存紀錄
                #endregion
                #region 檢驗出庫
                if (strFlag == "OUT")
                {

                    #region To異動庫存(IQC儲位庫存增加)
                    for (int i = 0; i < dtToStorage.Rows.Count; i++)
                    {
                        //整理異動的location
                        if (strTempLocatTo.IndexOf(dtToStorage.Rows[i]["LOCAT"].ToString()) < 0)
                        {
                            aryLocatTo.Add(dtToStorage.Rows[i]["LOCAT"].ToString());
                            aryLgortTo.Add(dtToStorage.Rows[i]["LGORT"].ToString());
                            strTempLocatTo += "++" + dtToStorage.Rows[i]["LOCAT"].ToString();
                        }

                        //insert data
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhecd.ResetField();

                        objWhecd.Mandt = MANDT;
                        objWhecd.Comcd = COMCD;
                        objWhecd.Werks = dtToStorage.Rows[i]["WERKS"].ToString();
                        objWhecd.Lgort = dtToStorage.Rows[i]["LGORT"].ToString();
                        objWhecd.Locat = dtToStorage.Rows[i]["LOCAT"].ToString();
                        objWhecd.Matnr = dtToStorage.Rows[i]["MATNR"].ToString();
                        objWhecd.Crdat = "GetDate()";
                        objWhecd.Alqty = dtToStorage.Rows[i]["ALQTY"].ToString();
                        objWhecd.Whusr = dtToStorage.Rows[i]["WHUSR"].ToString();
                        objWhecd.Qcusr = dtToStorage.Rows[i]["QCUSR"].ToString();
                        objWhecd.Qctyp = "O";//檢驗中
                        objWhecd.Remak = dtToStorage.Rows[i]["REMAK"].ToString();
                        objWhecd.Vbeln = dtToStorage.Rows[i]["VBELN"].ToString();
                        objWhecd.Pakid = "";

                        strSQL = objWhecd.EntityGetInsertSql();
                        arySQL.Add(strSQL);
                    }
                    #endregion
                    #region From異動庫存(WH儲位庫存減少)
                    for (int i = 0; i < dtFromStorage.Rows.Count; i++)
                    {
                        //整理異動的location
                        if (strTempLocatFrom.IndexOf(dtFromStorage.Rows[i]["LOCAT"].ToString()) < 0)
                        {
                            aryLocatFrom.Add(dtFromStorage.Rows[i]["LOCAT"].ToString());
                            strTempLocatFrom += "++" + dtFromStorage.Rows[i]["LOCAT"].ToString();
                        }

                        //更新
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhecd.ResetField();

                        objWhecd.Alqty = dtFromStorage.Rows[i]["ALQTY"].ToString();//實際庫存

                        alConditions.Add("Mandt= '" + MANDT + "'");
                        alConditions.Add("Comcd= '" + COMCD + "'");
                        alConditions.Add("Werks= '" + dtFromStorage.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add("Lgort= '" + dtFromStorage.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add("Locat= '" + dtFromStorage.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add("Matnr= '" + dtFromStorage.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add("Vbeln= '" + dtFromStorage.Rows[i]["VBELN"].ToString() + "'");

                        strSQL = objWhecd.EntityGetUpdateSql(alConditions);
                        arySQL.Add(strSQL);

                        //刪除庫存為0
                        objWhecd.ResetField();
                        alConditions.Clear();
                        alConditions.Add(" MANDT='" + MANDT + "'");
                        alConditions.Add(" COMCD='" + COMCD + "'");
                        alConditions.Add(" WERKS='" + dtFromStorage.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add(" LGORT='" + dtFromStorage.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add(" LOCAT='" + dtFromStorage.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add(" MATNR='" + dtFromStorage.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add(" ALQTY= 0 ");

                        arySQL.Add(objWhecd.EntityGetDeleteSql(alConditions));

                    }

                    #endregion
                }
                #endregion
                #region 檢驗入庫
                if (strFlag == "IN")
                {
                    #region To異動庫存
                    for (int i = 0; i < dtToStorage.Rows.Count; i++)
                    {
                        //整理異動的location
                        if (strTempLocatTo.IndexOf(dtToStorage.Rows[i]["LOCAT"].ToString()) < 0)
                        {
                            aryLocatTo.Add(dtToStorage.Rows[i]["LOCAT"].ToString());
                            aryLgortTo.Add(dtToStorage.Rows[i]["LGORT"].ToString());
                            strTempLocatTo += "++" + dtToStorage.Rows[i]["LOCAT"].ToString();
                        }
                        if (objStorageData.QueryDataExistsInWhecd(dtToStorage.Rows[i]["LGORT"].ToString(), dtToStorage.Rows[i]["LOCAT"].ToString(), dtToStorage.Rows[i]["MATNR"].ToString(), dtToStorage.Rows[i]["QCTYP"].ToString(), dtToStorage.Rows[i]["VBELN"].ToString()))
                        {
                            //update data
                            alColumns.Clear();
                            alConditions.Clear();
                            objWhecd.ResetField();

                            objWhecd.Alqty = "ALQTY + " + dtToStorage.Rows[i]["ALQTY"].ToString();
                            objWhecd.Qctyp = "";

                            alConditions.Add("Mandt= '" + MANDT + "'");
                            alConditions.Add("Comcd= '" + COMCD + "'");
                            alConditions.Add("Werks= '" + dtToStorage.Rows[i]["WERKS"].ToString() + "'");
                            alConditions.Add("Lgort= '" + dtToStorage.Rows[i]["LGORT"].ToString() + "'");
                            alConditions.Add("Locat= '" + dtToStorage.Rows[i]["LOCAT"].ToString() + "'");
                            alConditions.Add("Qctyp= '" + dtToStorage.Rows[i]["QCTYP"].ToString() + "'");
                            alConditions.Add("Matnr= '" + dtToStorage.Rows[i]["MATNR"].ToString() + "'");
                            alConditions.Add("Vbeln= '" + dtToStorage.Rows[i]["VBELN"].ToString() + "'");

                            strSQL = objWhecd.EntityGetUpdateSql(alConditions);
                            arySQL.Add(strSQL);
                        }
                        else
                        {
                            //insert data
                            alColumns.Clear();
                            alConditions.Clear();
                            objWhecd.ResetField();

                            objWhecd.Mandt = MANDT;
                            objWhecd.Comcd = COMCD;
                            objWhecd.Werks = dtToStorage.Rows[i]["WERKS"].ToString();
                            objWhecd.Lgort = dtToStorage.Rows[i]["LGORT"].ToString();
                            objWhecd.Locat = dtToStorage.Rows[i]["LOCAT"].ToString();
                            objWhecd.Matnr = dtToStorage.Rows[i]["MATNR"].ToString();
                            objWhecd.Crdat = "GetDate()";
                            objWhecd.Alqty = dtToStorage.Rows[i]["ALQTY"].ToString();
                            objWhecd.Whusr = dtToStorage.Rows[i]["WHUSR"].ToString();
                            objWhecd.Qcusr = dtToStorage.Rows[i]["QCUSR"].ToString();
                            objWhecd.Qctyp = dtToStorage.Rows[i]["QCTYP"].ToString();
                            objWhecd.Remak = dtToStorage.Rows[i]["REMAK"].ToString();
                            objWhecd.Vbeln = dtToStorage.Rows[i]["VBELN"].ToString();
                            objWhecd.Pakid = "";

                            strSQL = objWhecd.EntityGetInsertSql();
                            arySQL.Add(strSQL);
                        }
                    }


                    #endregion
                    #region From異動庫存
                    for (int i = 0; i < dtFromStorage.Rows.Count; i++)
                    {
                        //整理異動的location
                        if (strTempLocatFrom.IndexOf(dtFromStorage.Rows[i]["LOCAT"].ToString()) < 0)
                        {
                            aryLocatFrom.Add(dtFromStorage.Rows[i]["LOCAT"].ToString());
                            strTempLocatFrom += "++" + dtFromStorage.Rows[i]["LOCAT"].ToString();
                        }

                        //更新
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhecd.ResetField();

                        objWhecd.Alqty = dtFromStorage.Rows[i]["ALQTY"].ToString();

                        alConditions.Add("Mandt= '" + MANDT + "'");
                        alConditions.Add("Comcd= '" + COMCD + "'");
                        alConditions.Add("Werks= '" + dtFromStorage.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add("Lgort= '" + dtFromStorage.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add("Locat= '" + dtFromStorage.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add("Matnr= '" + dtFromStorage.Rows[i]["MATNR"].ToString() + "'");

                        alConditions.Add("Vbeln= '" + dtFromStorage.Rows[i]["VBELN"].ToString() + "'");
                        //
                        if (dtFromStorage.Rows[i]["LOCAT"].ToString() == "IQC001")
                        {
                            alConditions.Add("Qcusr= '" + dtFromStorage.Rows[i]["QCUSR"].ToString() + "'");
                        }
                        else
                        {
                            alConditions.Add("Qctyp= '" + dtFromStorage.Rows[i]["QCTYP"].ToString() + "'");//確認是否要加
                        }



                        strSQL = objWhecd.EntityGetUpdateSql(alConditions);
                        arySQL.Add(strSQL);

                        //刪除庫存為0
                        objWhecd.ResetField();
                        alConditions.Clear();
                        alConditions.Add(" MANDT='" + MANDT + "'");
                        alConditions.Add(" COMCD='" + COMCD + "'");
                        alConditions.Add(" WERKS='" + dtFromStorage.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add(" LGORT='" + dtFromStorage.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add(" LOCAT='" + dtFromStorage.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add(" MATNR='" + dtFromStorage.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add(" ALQTY= 0 ");

                        arySQL.Add(objWhecd.EntityGetDeleteSql(alConditions));

                    }

                    #endregion
                }
                #endregion

                #region 更新WHHED
                for (int i = 0; i < aryLocatTo.Count; i++)
                {
                    sbSql.Append("Update WHHED set  ");
                    sbSql.AppendFormat("  LOSTS=T.TOTAL from ");
                    sbSql.AppendFormat(" (Select TOTAL=case when count(*)>0 then '1' else '0' end  from whecd where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + WERKS + "' and LGORT= '" + aryLgortTo[i].ToString() + "' and LOCAT= '" + aryLocatTo[i].ToString() + "') as T  ");
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    sbSql.AppendFormat(" and LGORT='{0}' ", aryLgortTo[i].ToString());
                    sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocatTo[i].ToString());
                    arySQL.Add(sbSql.ToString());

                }
                for (int i = 0; i < aryLocatFrom.Count; i++)
                {
                    sbSql.Append("Update WHHED set  ");
                    sbSql.AppendFormat("  LOSTS=T.TOTAL from ");
                    sbSql.AppendFormat(" (Select TOTAL=case when count(*)>0 then '1' else '0' end  from whecd where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocatFrom[i].ToString() + "') as T  ");
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocatFrom[i].ToString());
                    arySQL.Add(sbSql.ToString());

                }
                #endregion

                bool bolReturn = false;
                try
                {
                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return bolReturn;

            }
