                strsql.AppendFormat("SELECT WERKS,MBLNR,WO,MATNR,SUM(MENGE) AS MENGE FROM WHDWN WHERE  MBLNR='{0}' GROUP BY WERKS,MBLNR,WO,MATNR", MBLNR);


