            #region 查詢半成品Hold资料
            //=================================================================================================================
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            /// <summary>
            /// 查詢半成品Hold资料
            /// </summary> 
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageData objStorageData =new QCI.QWMS.StorageData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataSet  dsData = objStorageData.QueryBoxIDStorageData(varPalletID, varBOXID);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            ///////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataTable Querywhlold(string werks, string lgort, string location, string boxid, bool checpn)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "Querywhlold";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);

                DataTable dtData = new DataTable();
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                StringBuilder strsql = new StringBuilder();
                if (checpn)
                {
                    strsql.AppendFormat("SELECT DISTINCT D.WERKS,D.LGORT,D.LOCAT,D.BOXID,D.MATNR,D.INSMK,D.CHARG,SUM(K.MENGE) AS MENGE,H.REMAK FROM WHHOLD AS H INNER JOIN WHDWN AS K ON H.SERNO=K.SERNO LEFT JOIN   WHBOX AS D ON K.BOXID=D.BOXID WHERE 1=1 ");
                }
                else
                {
                    strsql.AppendFormat("SELECT DISTINCT D.WERKS,D.LGORT,D.LOCAT,D.BOXID,K.SERNO,D.MATNR,D.INSMK,D.CHARG,K.MENGE,H.REMAK FROM WHHOLD AS H INNER JOIN WHDWN AS K ON H.SERNO=K.SERNO LEFT JOIN   WHBOX AS D ON K.BOXID=D.BOXID WHERE 1=1 ");
                }
                if (werks != "")
                {
                    strsql.AppendFormat(" AND K.WERKS='{0}'", werks);
                }
                if (lgort != "")
                {
                    strsql.AppendFormat(" AND K.LGORT='{0}'", lgort);
                }
                if (location != "")
                {
                    strsql.AppendFormat(" AND K.LOCAT='{0}'", location);
                }
                if (boxid != "")
                {
                    strsql.AppendFormat(" AND K.BOXID='{0}'", boxid);
                }

                if (checpn)
                {
                    strsql.AppendFormat("  GROUP BY D.WERKS,D.LGORT,D.LOCAT,D.BOXID,D.MATNR,D.INSMK,D.CHARG,H.REMAK ");
                }
                try
                {
                    ControlHandleDB();


                    dtData = ControlSqlAccess.GetDataTable(strsql.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return dtData;
            }

