            #region 当前储位是否是空储

            public bool QueryDataIsExistsInStorage(string strLocat, string strMatnr, string strBoxID)
            {

                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryDataIsExistsInStorage";
                this.ControlMethodParm = "(" + strLocat + "," + strMatnr + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataWhitm objWhitm = new DataWhitm(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alQueryConditions = new ArrayList();

                alColumns.Add("*");

                alQueryConditions.Add("MANDT = '" + MANDT + "'");
                alQueryConditions.Add("COMCD = '" + COMCD + "'");
                alQueryConditions.Add("WERKS = '" + WERKS + "'");
                alQueryConditions.Add("LGORT = '" + LGORT + "'");
                alQueryConditions.Add("LOCAT = '" + strLocat + "'");
                alQueryConditions.Add("MATNR = '" + strMatnr + "'");
                alQueryConditions.Add("INSMK IN ('G','J','S') ");
                alQueryConditions.Add("BOXID = '" + strBoxID + "'");

                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();
                    dtData = objWhitm.EntityQuery(alColumns, alQueryConditions, false, true);
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                if (dtData.Rows.Count > 0)
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }

            #endregion

            #region EC入库

            public bool AddIQCInData(DataTable dtStorage, DataTable dtData, DataTable dtVBELN)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddIQCInData";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                #region 變數宣告
                string strSQL = "";
                string strTempLocat = "";

                DataWhhed objWhhed = new DataWhhed(UserData);
                DataWhitm objWhitm = new DataWhitm(UserData);
                DataWhbox objWhbox = new DataWhbox(UserData);
                DataWhdwn objWhdwn = new DataWhdwn(UserData);

                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                StringBuilder sbSql = new StringBuilder();
                ArrayList arySQL = new ArrayList();
                ArrayList aryLocat = new ArrayList();
                #endregion

                #region WHLOG
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);
                arySQL = objLogData.AddLogData("", "", dtStorage);
                #endregion

                #region WHITM
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);
                DataTable dtBOX = dtData.Select("CHKED = true").CopyToDataTable<DataRow>();
                for (int i = 0; i < dtBOX.Rows.Count; i++)
                {
                    if (strTempLocat.IndexOf(dtBOX.Rows[i]["LOCAT"].ToString()) < 0)
                    {
                        aryLocat.Add(dtBOX.Rows[i]["LOCAT"].ToString());
                        strTempLocat += "++" + dtBOX.Rows[i]["LOCAT"].ToString();
                    }
                    //当前储位是否是空储
                    if (!QueryDataIsExistsInStorage(dtBOX.Rows[i]["LOCAT"].ToString(), dtBOX.Rows[i]["MATNR"].ToString(), dtBOX.Rows[i]["BOXID"].ToString()))
                    {
                        #region 良品
                        if (Convert.ToInt32(dtBOX.Rows[i]["ALGQTY"].ToString()) > 0)
                        {
                            alColumns.Clear();
                            alConditions.Clear();
                            objWhitm.ResetField();
                            objWhitm.Mandt = dtBOX.Rows[i]["MANDT"].ToString();
                            objWhitm.Comcd = dtBOX.Rows[i]["COMCD"].ToString();
                            objWhitm.Werks = dtBOX.Rows[i]["WERKS"].ToString();
                            objWhitm.Lgort = dtBOX.Rows[i]["LGORT"].ToString();
                            objWhitm.Locat = dtBOX.Rows[i]["LOCAT"].ToString();
                            objWhitm.Matnr = dtBOX.Rows[i]["MATNR"].ToString();
                            objWhitm.Insmk = dtBOX.Rows[i]["INSMK"].ToString();
                            objWhitm.Mblnr = "GOOD";
                            objWhitm.Charg = "";
                            objWhitm.Lifnr = "";
                            objWhitm.Ebeln = "";
                            objWhitm.Indat = dtBOX.Rows[i]["INDAT"].ToString();
                            objWhitm.Menge = dtBOX.Rows[i]["ALGQTY"].ToString();
                            objWhitm.Qcqty = "0";
                            objWhitm.Refno = "";
                            objWhitm.Mrgid = "";
                            objWhitm.Isptm = "";
                            objWhitm.Rmak1 = dtBOX.Rows[i]["RMAK1"].ToString();
                            objWhitm.Crnam = CRNAM;
                            objWhitm.Crdat = "GetDate()";
                            objWhitm.Monam = CRNAM;
                            objWhitm.Modat = "GetDate()";
                            objWhitm.Boxid = dtBOX.Rows[i]["BOXID"].ToString();
                            objWhitm.Serno = dtBOX.Rows[i]["BOXID"].ToString();
                            objWhitm.Locod = dtBOX.Rows[i]["LotCode"].ToString();
                            strSQL = objWhitm.EntityGetInsertSql();
                            arySQL.Add(strSQL);
                        }
                        #endregion
                        #region 不良品
                        if (Convert.ToInt32(dtBOX.Rows[i]["ALSQTY"].ToString()) > 0)
                        {
                            alColumns.Clear();
                            alConditions.Clear();
                            objWhitm.ResetField();
                            objWhitm.Mandt = dtBOX.Rows[i]["MANDT"].ToString();
                            objWhitm.Comcd = dtBOX.Rows[i]["COMCD"].ToString();
                            objWhitm.Werks = dtBOX.Rows[i]["WERKS"].ToString();
                            objWhitm.Lgort = dtBOX.Rows[i]["LGORT"].ToString();
                            objWhitm.Locat = dtBOX.Rows[i]["LOCAT"].ToString();
                            objWhitm.Matnr = dtBOX.Rows[i]["MATNR"].ToString();
                            objWhitm.Insmk = "S";
                            objWhitm.Mblnr = "REJECT";
                            objWhitm.Charg = "";
                            objWhitm.Lifnr = "";
                            objWhitm.Ebeln = "";
                            objWhitm.Indat = dtBOX.Rows[i]["INDAT"].ToString();
                            objWhitm.Menge = dtBOX.Rows[i]["ALSQTY"].ToString();
                            objWhitm.Qcqty = "0";
                            objWhitm.Refno = "";
                            objWhitm.Mrgid = "";
                            objWhitm.Isptm = "";
                            objWhitm.Rmak1 = dtBOX.Rows[i]["RMAK1"].ToString();
                            objWhitm.Crnam = CRNAM;
                            objWhitm.Crdat = "GetDate()";
                            objWhitm.Monam = CRNAM;
                            objWhitm.Modat = "GetDate()";
                            objWhitm.Boxid = dtBOX.Rows[i]["BOXID"].ToString();
                            objWhitm.Serno = dtBOX.Rows[i]["BOXID"].ToString();
                            objWhitm.Locod = dtBOX.Rows[i]["LotCode"].ToString();
                            strSQL = objWhitm.EntityGetInsertSql();
                            arySQL.Add(strSQL);
                        }
                        #endregion
                    }
                    else
                    {
                        #region 良品
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhitm.ResetField();
                        objWhitm.Menge = "MENGE +" + dtBOX.Rows[i]["ALGQTY"].ToString();
                        objWhitm.Rmak1 = dtBOX.Rows[i]["RMAK1"].ToString();
                        objWhitm.Monam = CRNAM;
                        objWhitm.Modat = "GetDate()";
                        alConditions.Add("Mandt= '" + dtBOX.Rows[i]["MANDT"].ToString() + "'");
                        alConditions.Add("Comcd= '" + dtBOX.Rows[i]["COMCD"].ToString() + "'");
                        alConditions.Add("Werks= '" + dtBOX.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add("Lgort= '" + dtBOX.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add("Locat= '" + dtBOX.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add("Matnr= '" + dtBOX.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add("Insmk= '" + dtBOX.Rows[i]["Insmk"].ToString() + "'");
                        alConditions.Add("Mblnr= 'GOOD'");
                        alConditions.Add("BOXID = '" + dtBOX.Rows[i]["BOXID"].ToString() + "'");
                        strSQL = objWhitm.EntityGetUpdateSql(alConditions);
                        arySQL.Add(strSQL);
                        #endregion
                        #region 不良品
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhitm.ResetField();
                        objWhitm.Menge = "MENGE +" + dtBOX.Rows[i]["ALSQTY"].ToString();
                        objWhitm.Rmak1 = dtBOX.Rows[i]["RMAK1"].ToString();
                        objWhitm.Monam = CRNAM;
                        objWhitm.Modat = "GetDate()";
                        alConditions.Add("Mandt= '" + dtBOX.Rows[i]["MANDT"].ToString() + "'");
                        alConditions.Add("Comcd= '" + dtBOX.Rows[i]["COMCD"].ToString() + "'");
                        alConditions.Add("Werks= '" + dtBOX.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add("Lgort= '" + dtBOX.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add("Locat= '" + dtBOX.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add("Matnr= '" + dtBOX.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add("Insmk= 'S'");
                        alConditions.Add("Mblnr= 'REJECT'");
                        alConditions.Add("BOXID = '" + dtBOX.Rows[i]["BOXID"].ToString() + "'");
                        strSQL = objWhitm.EntityGetUpdateSql(alConditions);
                        arySQL.Add(strSQL);
                        #endregion
                    }
                }
                #endregion

                #region WHHED
                for (int i = 0; i < aryLocat.Count; i++)
                {
                    sbSql.Remove(0, sbSql.Length);
                    sbSql.Append("Update WHHED set  ");
                    sbSql.AppendFormat("  LOSTS=T.TOTAL from ");
                    sbSql.AppendFormat(" (Select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "' and COMCD='" + COMCD + "') as T  ");
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocat[i].ToString());
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    arySQL.Add(sbSql.ToString());

                    //sbSql.Remove(0, sbSql.Length);
                    //sbSql.Append("Update WHHED set  ");
                    //sbSql.AppendFormat("  ISMRG=T.ISMRG from ");
                    //sbSql.AppendFormat(" (Select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "'  and WERKS= '" + WERKS + "' and LGORT= '" + LGORT + "' and LOCAT= '" + aryLocat[i].ToString() + "' and COMCD='" + COMCD + "' and MRGID<>'') as T  ");
                    //sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    //sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    //sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    //sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocat[i].ToString());
                    //sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    //arySQL.Add(sbSql.ToString());
                }
                #endregion

                #region ECBOX
                for (int i = 0; i < dtBOX.Rows.Count; i++)
                {
                    sbSql.Remove(0, sbSql.Length);
                    sbSql.Append("UPDATE ECBOX SET FLAGE = 'Y' ");
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    sbSql.AppendFormat(" and VBELN='{0}' ", dtBOX.Rows[i]["VBELN"].ToString());
                    sbSql.AppendFormat(" and BOXID='{0}' ", dtBOX.Rows[i]["BOXID"].ToString());
                    sbSql.AppendFormat(" and MATNR='{0}' ", dtBOX.Rows[i]["MATNR"].ToString());

                    if (arySQL.IndexOf(sbSql.ToString()) < 0)
                        arySQL.Add(sbSql.ToString());
                }
                #endregion

                #region WHDWN

                foreach (DataRow dr in dtVBELN.Rows)
                {
                    //良品
                    sbSql.Remove(0, sbSql.Length);
                    sbSql.AppendFormat("UPDATE WHDWN SET OTQTY = OTQTY + {0}", dr["ALQTY"].ToString());
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    sbSql.AppendFormat(" and WERKS='{0}' ", WERKS);
                    sbSql.AppendFormat(" and LGORT='{0}' ", LGORT);
                    sbSql.AppendFormat(" and MBLNR='{0}' ", dr["MBLNR"].ToString());
                    sbSql.AppendFormat(" and MATNR='{0}' ", dr["MATNR"].ToString());
                    arySQL.Add(sbSql.ToString());
                }

                #endregion

                #region 明广需要添加Lotinfo
                if (UserData.CompanyCode == "2280")
                {
                    for (int i = 0; i < dtBOX.Rows.Count; i++)
                    {
                        //sbSql.Remove(0, sbSql.Length);

                        string SQLlot = "insert into Lotinfo(LOTNUM,LOPQTY,LORQTY,QCIMAT,LOTDAT,Uflage,BoxID) values( '" + dtBOX.Rows[i]["LotCode"].ToString() + "'," + dtBOX.Rows[i]["ALGQTY"].ToString() + "," + dtBOX.Rows[i]["ALSQTY"].ToString() + ",'" + dtBOX.Rows[i]["MATNR"].ToString() + "','" + dtBOX.Rows[i]["INDAT"].ToString() + "','" + "N" + "','" + dtBOX.Rows[i]["BOXID"].ToString() + "')";
                        arySQL.Add(SQLlot.ToString());
                    }
                }
                #endregion

                bool bolReturn = false;
                try
                {
                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return bolReturn;
            }


