            #region IQC借还料

            public bool IQCBorrowMaterialsData(DataTable dtData, string strFlag)
            {
                bool blReturn = false;

                try
                {
                    string strSQL = "";
                    string strDetailSql = "";
                    string strTemp = "";
                    ArrayList arySQL = new ArrayList();
                    ControlHandleDB();
                    for (int i = 0; i < dtData.Rows.Count; i++)
                    {
                        //if (dtData.Rows[i]["RTIQCID"].ToString() == "" || dtData.Rows[i]["RTWHID"].ToString() == "")//借料
                        if (strFlag == "Borrow" && (Int32.Parse(dtData.Rows[i]["BRQTY"].ToString()) - Int32.Parse(dtData.Rows[i]["OldBRQTY"].ToString())) > 0)//借料
                        {
                            // #region 
                            strTemp = @"SELECT * FROM WHBRM WHERE MBLNR='" + dtData.Rows[i]["MBLNR"].ToString() + "' AND Remark=''";
                            DataTable dtTemp = ControlSqlAccess.GetDataTable(strTemp);
                            if (dtTemp.Rows.Count > 0)//判断是否已借过料，已借过做update，未借过做insert
                            {
                                strSQL = @"UPDATE WHBRM SET BRQTY=" + dtData.Rows[i]["BRQTY"].ToString() + ",IQCID='" + dtData.Rows[i]["IQCID"].ToString() + "',WHID='" + dtData.Rows[i]["WHID"].ToString() + "'," +
                                         "CRDAT=GETDATE(),USRNM='" + CRNAM + "' WHERE MBLNR='" + dtData.Rows[i]["MBLNR"].ToString() + "' AND Remark = ''";
                                arySQL.Add(strSQL);

                                strDetailSql = @"INSERT INTO WHBRM (MBLNR,BWART,MATNR,INDAT,WERKS,LGORT,LOCAT,MENGE,BRQTY,CRDAT,IQCID,WHID,LIFNR,USRNM,Remark) "+
                                                    "VALUES('" + dtData.Rows[i]["MBLNR"].ToString() + "','" + dtData.Rows[i]["BWART"].ToString() + "','" + dtData.Rows[i]["MATNR"].ToString() +"'," +
                                                    "'" + dtData.Rows[i]["BUDAT"].ToString() + "','" + dtData.Rows[i]["WERKS"].ToString() + "','" + dtData.Rows[i]["LGORT"].ToString() + "'," +
                                                    "'" + dtData.Rows[i]["LOCAT"].ToString() + "','" + dtData.Rows[i]["MENGE"].ToString() + "','" + (Int32.Parse(dtData.Rows[i]["BRQTY"].ToString()) - Int32.Parse(dtData.Rows[i]["OldBRQTY"].ToString())).ToString() + "'," +
                                                    "GETDATE(),'" + dtData.Rows[i]["IQCID"].ToString() + "','" + dtData.Rows[i]["WHID"].ToString() + "','" + dtData.Rows[i]["LIFNR"].ToString() + "'," +
                                                    "'" + CRNAM + "','borrow')";
                                arySQL.Add(strDetailSql);
                            }
                            else
                            {
                                strSQL = @"INSERT INTO WHBRM (MBLNR,BWART,MATNR,INDAT,WERKS,LGORT,LOCAT,MENGE,BRQTY,RTQTY,CRDAT,IQCID,WHID,RTIQCID,RTWHID,LIFNR,USRNM,Remark) "+
                                    "VALUES('" + dtData.Rows[i]["MBLNR"].ToString() + "','" +
                                     dtData.Rows[i]["BWART"].ToString() + "','" + dtData.Rows[i]["MATNR"].ToString() +
                                     "','" + dtData.Rows[i]["BUDAT"].ToString() + "'," +
                                     "'" + dtData.Rows[i]["WERKS"].ToString() + "','" + dtData.Rows[i]["LGORT"].ToString() + "','" + dtData.Rows[i]["LOCAT"].ToString() + "'," +
                                     dtData.Rows[i]["MENGE"].ToString() + "," + dtData.Rows[i]["BRQTY"].ToString() +
                                     ",'0',GETDATE(),'" + dtData.Rows[i]["IQCID"].ToString() + "','" +
                                     dtData.Rows[i]["WHID"].ToString() + "'," +
                                     "'','','" + dtData.Rows[i]["LIFNR"].ToString() + "','" + CRNAM + "','')";
                                arySQL.Add(strSQL);

                                strDetailSql = @"INSERT INTO WHBRM (MBLNR,BWART,MATNR,INDAT,WERKS,LGORT,LOCAT,MENGE,BRQTY,CRDAT,IQCID,WHID,LIFNR,USRNM,Remark) " +
                                                    "VALUES('" + dtData.Rows[i]["MBLNR"].ToString() + "','" + dtData.Rows[i]["BWART"].ToString() + "','" + dtData.Rows[i]["MATNR"].ToString() + "'," +
                                                    "'" + dtData.Rows[i]["BUDAT"].ToString() + "','" + dtData.Rows[i]["WERKS"].ToString() + "','" + dtData.Rows[i]["LGORT"].ToString() + "'," +
                                                    "'" + dtData.Rows[i]["LOCAT"].ToString() + "','" + dtData.Rows[i]["MENGE"].ToString() + "','" + (Int32.Parse(dtData.Rows[i]["BRQTY"].ToString()) - Int32.Parse(dtData.Rows[i]["OldBRQTY"].ToString())).ToString() + "'," +
                                                    "GETDATE(),'" + dtData.Rows[i]["IQCID"].ToString() + "','" + dtData.Rows[i]["WHID"].ToString() + "','" + dtData.Rows[i]["LIFNR"].ToString() + "'," +
                                                    "'" + CRNAM + "','borrow')";
                                arySQL.Add(strDetailSql);
                            }
                        }
                        if (strFlag == "Return" && (Int32.Parse(dtData.Rows[i]["RTQTY"].ToString()) - Int32.Parse(dtData.Rows[i]["OldRTQTY"].ToString())) > 0)
                        {
                            strSQL = @"UPDATE WHBRM SET RTQTY=" + dtData.Rows[i]["RTQTY"].ToString() +
                                     ",BRQTY="+ dtData.Rows[i]["BRQTY"].ToString() + ",RTDAT=GETDATE(),RTIQCID='" + dtData.Rows[i]["RTIQCID"].ToString() +
                                     "',RTWHID='" + dtData.Rows[i]["RTWHID"].ToString() + "',USRNM='" + CRNAM +
                                     "' WHERE" +
                                     " MBLNR='" + dtData.Rows[i]["MBLNR"].ToString() + "' AND Remark=''";
                            arySQL.Add(strSQL);

                            strDetailSql = @"INSERT INTO WHBRM (MBLNR,BWART,MATNR,INDAT,WERKS,LGORT,LOCAT,MENGE,RTQTY,RTDAT,RTIQCID,RTWHID,LIFNR,USRNM,Remark) " +
                                                "VALUES('" + dtData.Rows[i]["MBLNR"].ToString() + "','" + dtData.Rows[i]["BWART"].ToString() + "','" + dtData.Rows[i]["MATNR"].ToString() + "','" + dtData.Rows[i]["BUDAT"].ToString() + "'," +
                                                "'" + dtData.Rows[i]["WERKS"].ToString() + "','" + dtData.Rows[i]["LGORT"].ToString() + "','" + dtData.Rows[i]["LOCAT"].ToString() + "'," +
                                                "'" + dtData.Rows[i]["MENGE"].ToString() + "','" + (Int32.Parse(dtData.Rows[i]["RTQTY"].ToString()) - Int32.Parse(dtData.Rows[i]["OldRTQTY"].ToString())).ToString() + "',GETDATE(),'" + dtData.Rows[i]["RTIQCID"].ToString() + "','" + dtData.Rows[i]["RTWHID"].ToString() + "'," +
                                                "'" + dtData.Rows[i]["LIFNR"].ToString() + "','" + CRNAM + "','return')";
                            arySQL.Add(strDetailSql);
                        }
                    }

                    blReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- UpdateStatus()";
                }
                return blReturn;
            }

