            #region  获取QMS数据库配置
            /// <summary>
            /// 获取QMS数据库配置
            /// </summary>
            /// <param name="MBLNR"></param>
            /// <returns></returns>
            public string GetQMSDBconn(string MBLNR)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetQMSDBconn";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                string DBcon = string.Empty;
                try
                {
                    string strType = MBLNR.Substring(0, 6);
                    string strPalletType = MBLNR.Substring(0, 1);
                    DataTable dtData = new DataTable();
                    string strsql = string.Format(@"SELECT * FROM dbo.WHCTRL WITH(NOLOCK)  WHERE  SOLDTO ='QMS'  AND CTRLID ='DB'");

                    if (string.Format("1;0").Contains(strPalletType))
                    {
                        strsql += string.Format(@" AND  CTRLNM ='0;1' AND  CTRLC1  LIKE '%{0}%'", strType);
                    }
                    else
                    {
                        strsql += string.Format(@"  AND CTRLNM ='{0}' ", strPalletType);
                    }

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strsql.ToString());
                    ControlSqlAccess.CloseConnection();

                    if (dtData.Rows.Count != 1)
                    {
                        throw new Exception("QMS DB 配置错误！");
                    }
                    else
                    {
                        DBcon = dtData.Rows[0]["CTRLC2"].ToString().Trim();
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessagero
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return DBcon;
            }
            #endregion

