            #region 定义内存表dtResponse的表结构
            /// <summary>
            /// 定义内存表dtResponse的表结构
            /// </summary>
            /// <param name="varMTYPE"></param>
            /// <param name="dtResponse"></param>
            private void createDtResponse(string varMTYPE, ref  DataTable dtResponse)
            {
                DataColumnCollection columns = dtResponse.Columns;
                if (varMTYPE.ToUpper() == "QMS_311")
                {
                    columns.Add("MBLNR", typeof(System.String)); //棧板號
                    columns.Add("WERKS", typeof(System.String)); //厂区
                    columns.Add("MATNR", typeof(System.String)); //料号
                    columns.Add("KOSTL", typeof(System.String)); //成本中心
                    columns.Add("FLGRT", typeof(System.String)); //转出仓
                    columns.Add("LGORT", typeof(System.String)); //转入仓
                    columns.Add("QTY", typeof(System.Decimal)); //數量
                    columns.Add("CHARG", typeof(System.String)); //版本
                    columns.Add("STATUS", typeof(System.String)); //状态
                    columns.Add("RESULT", typeof(System.String)); //SAP回傳的結果
                    //columns.Add("REMARK1", typeof(System.String)); //備註1
                    columns.Add("REMARK2", typeof(System.String)); //備註2
                }
                else if (varMTYPE.ToUpper() == "QMS")
                {
                    columns.Add("MBLNR", typeof(System.String)); //棧板號
                    columns.Add("PLANT", typeof(System.String)); //厂区
                    columns.Add("COSTCENTER", typeof(System.String)); //成本中心
                    columns.Add("WO", typeof(System.String)); //工單號
                    columns.Add("QTY", typeof(System.Decimal)); //數量
                    columns.Add("MATERIAL", typeof(System.String)); //料號
                    columns.Add("REGION", typeof(System.String)); //區域
                    columns.Add("LOCATION", typeof(System.String)); //仓别
                    columns.Add("REF1", typeof(System.String)); //版本
                    columns.Add("REF2", typeof(System.String)); //标记
                    columns.Add("RESULT", typeof(System.String)); //SAP回傳的結果
                    columns.Add("REMARK1", typeof(System.String)); //備註1
                    columns.Add("REMARK2", typeof(System.String)); //備註2
                }
                else if (varMTYPE.ToUpper() == "QMS_262")
                {
                    columns.Add("WERKS", typeof(String));//厂区
                    columns.Add("MBLNR", typeof(String));//栈板号
                    columns.Add("AUFNR", typeof(String));//工单号
                    columns.Add("MATNR", typeof(String));//料号
                    columns.Add("CHARG", typeof(String));//版本
                    columns.Add("MENGE", typeof(String));//退料数量
                    columns.Add("LGORT", typeof(String));//仓别
                    columns.Add("S", typeof(String));//标记栏位
                    columns.Add("RESULT", typeof(String));//扣帐编号
                    columns.Add("REMARK2", typeof(String));//退料错误信息
                }
            }
            #endregion

            #region  循环检查路径下是否已经产生文档
            /// <summary>
            /// 循环检查路径下是否已经产生文档
            /// </summary>
            /// <param name="strSAPOutPath"></param>
            /// <param name="AccessAccount"></param>
            /// <param name="AccessPassword"></param>
            /// <param name="strFileName"></param>
            /// <returns></returns>
            public bool CheckSAPDoc(string strSAPOutPath, string AccessAccount, string AccessPassword, string strFileName)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "CheckSAPDoc";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                try
                {
                    #region CODE IS HERE

                    bool blResult = false;
                    NetBeuiConnect objNetBuei = new NetBeuiConnect();
                    try
                    {

                        if (!string.IsNullOrEmpty(strSAPOutPath))
                        {
                            objNetBuei.LoginFileServer(strSAPOutPath, AccessAccount, AccessPassword);
                        }
                        else
                        {
                            throw new Exception("未找到SAP路径！");
                        }
                        for (int time = 0; time < 15; time++)
                        {
                            if (!blResult)
                            {
                                Thread.Sleep(10000);
                                string[] arrInputFiles = System.IO.Directory.GetFiles(strSAPOutPath, "*.OK");
                                foreach (string strInputFile in arrInputFiles)
                                {
                                    //if (strInputFile.Contains(strFileName))
                                    if (strInputFile.ToUpper().Contains(strFileName.ToUpper()))
                                    {
                                        blResult = true;
                                    }
                                }
                            }
                            else
                            {
                                time = 15;
                            }
                        }
                    }
                    catch
                    {
                        blResult = false;
                    }
                    finally
                    {
                        objNetBuei.Logoff();
                    }
                    return blResult;

                    #endregion
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                } //可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
            #endregion

            #region 将sapData中的数据解析到dtResponse中
            /// <summary>
            /// 将sapData中的数据解析到dtResponse中
            /// </summary>
            /// <param name="varMTYPE"></param>
            /// <param name="dtResponse"></param>
            /// <param name="sapData"></param>
            private void LoadSAPDateToDtResponse(string varMTYPE, ref  DataTable dtResponse, DataTable sapData)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "LoadSAPDateToDtResponse";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                try
                {
                    if (varMTYPE.ToUpper() == "QMS_311")
                    {
                        for (int i = 0; i < sapData.Rows.Count; i++)
                        {
                            DataRow dr = dtResponse.NewRow();
                            dr[0] = sapData.Rows[i]["1"].ToString().Trim();
                            dr[1] = sapData.Rows[i]["2"].ToString().Trim();
                            dr[2] = sapData.Rows[i]["3"].ToString().Trim();
                            dr[3] = sapData.Rows[i]["4"].ToString().Trim();
                            dr[4] = sapData.Rows[i]["5"].ToString().Trim();
                            dr[5] = sapData.Rows[i]["6"].ToString().Trim();
                            dr[6] = sapData.Rows[i]["7"].ToString().Trim();
                            dr[7] = sapData.Rows[i]["8"].ToString().Trim();
                            dr[8] = sapData.Rows[i]["9"].ToString().Trim();
                            dr[9] = sapData.Rows[i]["10"].ToString().Trim();
                            dr["REMARK2"] = sapData.Rows[i]["11"].ToString().Trim();
                            //dr[10] = sapData.Rows[i]["12"].ToString().Trim();
                            //dr[11] = sapData.Rows[i]["11"].ToString().Trim();
                            dtResponse.Rows.Add(dr);
                        }
                    }
                    else if (varMTYPE.ToUpper() == "QMS")
                    {
                        for (int i = 0; i < sapData.Rows.Count; i++)
                        {
                            DataRow dr = dtResponse.NewRow();
                            dr[0] = sapData.Rows[i]["1"].ToString().Trim();
                            dr[1] = sapData.Rows[i]["2"].ToString().Trim();
                            dr[2] = sapData.Rows[i]["3"].ToString().Trim();
                            dr[3] = sapData.Rows[i]["4"].ToString().Trim();
                            dr[4] = sapData.Rows[i]["5"].ToString().Trim();
                            dr[5] = sapData.Rows[i]["6"].ToString().Trim();
                            dr[6] = sapData.Rows[i]["7"].ToString().Trim();
                            dr[7] = sapData.Rows[i]["8"].ToString().Trim();
                            dr[8] = sapData.Rows[i]["9"].ToString().Trim();

                            dr[10] = sapData.Rows[i]["11"].ToString().Trim();
                            dr[11] = sapData.Rows[i]["12"].ToString().Trim();
                            dr[12] = sapData.Rows[i]["13"].ToString().Trim();
                            dtResponse.Rows.Add(dr);
                        }
                    }
                    else if (varMTYPE.ToUpper() == "QMS_262")
                    {
                        for (int i = 0; i < sapData.Rows.Count; i++)
                        {
                            DataRow dr = dtResponse.NewRow();
                            dr["WERKS"] = sapData.Rows[i]["1"].ToString().Trim();
                            dr["MBLNR"] = sapData.Rows[i]["2"].ToString().Trim();
                            dr["AUFNR"] = sapData.Rows[i]["3"].ToString().Trim();
                            dr["MATNR"] = sapData.Rows[i]["4"].ToString().Trim();
                            dr["CHARG"] = sapData.Rows[i]["5"].ToString().Trim();
                            dr["MENGE"] = sapData.Rows[i]["6"].ToString().Trim();
                            dr["LGORT"] = sapData.Rows[i]["7"].ToString().Trim();
                            dr["S"] = sapData.Rows[i]["8"].ToString().Trim();
                            dr["RESULT"] = sapData.Rows[i]["9"].ToString().Trim();
                            dr["REMARK2"] = sapData.Rows[i]["10"].ToString().Trim();
                            dtResponse.Rows.Add(dr);
                        }
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
