            # region 拆板 拼板操作
            /// <summary>
            /// 
            /// </summary>
            /// <param name="strLocat"></param>
            /// <param name="strNewLocat"></param>
            /// <param name="dtStorage"></param>
            /// <returns></returns>

            public bool PalletDataModify(DataTable dtSource, DataTable dtDestination)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "PalletDataModify";
                this.ControlMethodParm = "('" + dtSource + "','" + dtDestination + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    ArrayList arySQL = new ArrayList();
                    ArrayList aryLocat = new ArrayList();
                    LogData objLogData = new LogData(UserData, WERKS, LGORT, PROGID);
                    StorageData objStorage = new StorageData(UserData, WERKS, LGORT);
                    DataWhitm objDataWhitm = new DataWhitm(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    DataWhbox objDataWhbox = new DataWhbox(UserData);
                    string strSQL;


                    //WHLOG
                    arySQL = objLogData.AddLogData("", "", dtSource);
                    foreach (string list in objLogData.AddLogData("", "", dtDestination))
                    {
                        arySQL.Add(list);
                    }

                    //WHITM

                    foreach (DataRow dr in dtSource.Rows)
                    {
                        if (objStorage.QueryStoragePalletData(dr["MBLNR"].ToString(), "").Rows.Count > 0)
                        {
                            strSQL =
                                string.Format(@"UPDATE  dbo.WHITM SET MENGE =MENGE -{0},MONAM='{1}',MODAT =GETDATE() WHERE   MANDT ='{2}' AND COMCD ='{3}' AND WERKS='{4}' AND LGORT ='{5}'
AND MBLNR ='{6}' AND LOCAT ='{7}' AND MATNR ='{8}' AND INSMK ='{9}' AND CHARG ='{10}' ;", dr["ALQTY"], CRNAM,
                                    dr["MANDT"], dr["COMCD"], dr["WERKS"], dr["LGORT"],
                                    dr["MBLNR"], dr["LOCAT"], dr["MATNR"], dr["INSMK"], dr["CHARG"]);
                            arySQL.Add(strSQL);

                            arySQL.Add(DeleteZoreWhitem(dr["MANDT"].ToString(), dr["COMCD"].ToString(), dr["WERKS"].ToString(), dr["LGORT"].ToString(), dr["LOCAT"].ToString(),
                                  dr["MATNR"].ToString(), dr["INSMK"].ToString(), dr["MBLNR"].ToString(), dr["CHARG"].ToString()));

                            arySQL.Add(UpdateWhhED(dr["LOCAT"].ToString()));
                        }
                        else
                        {
                            throw new Exception(dr["MBLNR"].ToString() + "已经不存在，无法完成此操作");
                        }
                    }
                    foreach (DataRow dr in dtDestination.Rows)
                    {
                        if (objStorage.QueryStoragePalletData(dr["MBLNR"].ToString(), "").Rows.Count > 0)
