                StringBuilder strsql = new StringBuilder();
                MTYPE = QueryWHDWN_SEMIGBMTYPE(MBLNR);

                switch (MTYPE.Trim().ToUpper())
                {
                    case "QMS_262":
                        strsql.Append(" SELECT WERKS, MBLNR, WO, MATNR, CHARG, SUM(ISNULL(MENGE,0)) AS QTY, LGORT FROM WHDWN WITH(NOLOCK) WHERE MTYPE ='QMS_262'")
                              .AppendFormat(" AND MBLNR='{0}' AND MANDT='{1}' AND WERKS='{2}' AND LGORT='{3}'  GROUP BY WERKS, MBLNR, WO, MATNR, CHARG, LGORT ", MBLNR.Trim(), MANDT, WERKS, LGORT);
                        break;

                    case "QMS_311":
                        strsql.Append(" SELECT  MBLNR,WERKS,MATNR,ISNULL(KOSTL,'') AS KOSTL, FLGRT,LGORT,SUM(MENGE) AS QTY,CHARG,'' STATUS,''  RESULT,'' REMARK2 FROM WHDWN WITH(NOLOCK) WHERE MTYPE='QMS_311' ")
                        .AppendFormat("AND MBLNR='{0}' AND MANDT='{1}' AND WERKS='{2}' AND LGORT='{3}'    GROUP BY MBLNR,WERKS,KOSTL,MATNR,FLGRT,LGORT,CHARG ", MBLNR.Trim(), MANDT, WERKS, LGORT);
                        break;
                    default: throw new Exception("未找到扣帐数据！");
                        break;

                }
                try
                {
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strsql.ToString());
                    ControlSqlAccess.CloseConnection();
                }
