            public DataTable QueryDataForSap(string MBLNR, out  string MTYPE)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryDataForSap";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);
                DataTable dtData = new DataTable();
                StringBuilder strsql = new StringBuilder();

                MTYPE = QueryWHDWN_SEMIGBMTYPE(MBLNR);
                switch (MTYPE.Trim().ToUpper())
                {
                    case "QMS":
                        strsql.Append(" SELECT  MBLNR,WERKS,ISNULL(KOSTL,'') AS KOSTL,WO,SUM(MENGE) AS QTY,MATNR,REGION,LGORT,CHARG,'QWMS_QSMC'+CONVERT(VARCHAR(8),GETDATE(),112)  AS REF2 FROM WHDWN WITH(NOLOCK) WHERE MTYPE IN ('QMS','QMS_311') ")
                           .AppendFormat(" AND MBLNR='{0}' AND MANDT='{1}' AND COMCD='{4}' AND WERKS='{2}' AND LGORT='{3}'  GROUP BY MBLNR,WERKS,KOSTL,WO,MATNR,REGION,LGORT,CHARG ",
                               MBLNR.Trim(), MANDT, WERKS, LGORT, COMCD);
                        break;

                    case "QMS_311":
                        strsql.Append(
                            " SELECT  MBLNR,WERKS,MATNR,ISNULL(KOSTL,'') AS KOSTL, OTLGT,LGORT,SUM(MENGE) AS QTY,CHARG,'T' AS STATUS FROM WHDWN WITH(NOLOCK) WHERE MTYPE='QMS_311' ")
                        .AppendFormat(
                            "AND MBLNR='{0}' AND MANDT='{1}' AND COMCD='{4}' AND WERKS='{2}' AND LGORT='{3}'    GROUP BY MBLNR,WERKS,KOSTL,MATNR,OTLGT,LGORT,CHARG ", MBLNR.Trim(), MANDT, WERKS, LGORT, COMCD);
                        break;
                    default: 
                        throw new Exception("未找到扣帐数据！");
                }
                try
                {
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strsql.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return dtData;
            }
