            //=======================================================================================================================================
            /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            /// <summary>
            /// CSMC半成品入庫
            /// </summary> 
            /// <param name="strLocat">儲位。</param>
            /// <param name="dtStorage">庫存資料。</param>
            /// <returns>
            /// bool。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.StorageIn objStorageIn =new QCI.QWMS.StorageIn(strConnectionString,strMandt,strWerks,strLgort,strMblnr,strProgid,strCrnam);
            ///  bool  bolReturn = objStorageIn.AddSemiProdOnLineInData(strLocat,dtStorage);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            /////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////	
            public bool AddSemiProdTransferInData_GB(DataTable dtInStorage, DataTable dtOutStorage, string varLocat)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddSemiProdTransferInData";
                this.ControlMethodParm = "()";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                #region 變數宣告

                ArrayList arySQL = new ArrayList();
                string sqlWhdwn = string.Empty;
                string sqlWhitm = string.Empty;
                string sqlWhtra = string.Empty;
                string sqlwhbox = string.Empty;

                DataWhitm objWhitm = new DataWhitm(UserData);

                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                StringBuilder sbSql = new StringBuilder();
                bool bolReturn = false;
                #endregion

                #region WHLOG
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);
                arySQL = objLogData.AddLogData("", "", dtInStorage);
                #endregion

                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);



                foreach (DataRow dr in dtInStorage.Rows)
                {
                    //计算出的数据
                    int OutCount = 0;
                    foreach (DataRow outRow in dtOutStorage.Rows)
                    {
                        OutCount += Convert.ToInt32(outRow["MENGE"].ToString());
                    }

                    #region whitm
                    if (!objStorageData.QueryDataExistsInStorage(varLocat, dr["MATNR"].ToString(), dr["INSMK"].ToString(), "GB", dr["CHARG"].ToString(), dr["SERNO"].ToString(), "", ""))
                    {
                        alColumns.Clear();
                        alConditions.Clear();
