            public string AddLocatLogSQL(string BOXID, string MATNR, string REMARK, int QTY)
            {
                return string.Format(@"INSERT INTO LOCAT_LOG(WERKS, BOXID, MATNR, QTY, REMARK, CRTDAT) VALUES('{0}','{1}','{2}', {3}, N'{4}',GETDATE())", WERKS, BOXID, MATNR, QTY, REMARK);
            }

