            //与SAP交互(Write)
            public DataTable WriteSapFile_CSMC_BP(DataTable dtData, string varMTYPE)
            {
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);
                DataTable dtResponse = new DataTable();
                try
                {
                    #region SAP PATH

                    string strFileHeader = string.Empty;
                    switch (varMTYPE)
                    {
                        case "QMS_311":
                            strFileHeader = "EC027_";
                            break;
                        case "QMS_262":
                            strFileHeader = "EC035_";
                            break;
                        default: throw new Exception("单据类型不明确");
                            break;
                    }

                    DataTable dtSAPPath = new DataTable();
                    dtSAPPath = GetSAPFilePath(strFileHeader);

                    string strFileInPath_CSMC = dtSAPPath.Rows[0]["CTRLC1"].ToString().Trim();
                    string strFileOutPath_CSMC = dtSAPPath.Rows[0]["CTRLC2"].ToString().Trim();
                    string strFilePathAccount = dtSAPPath.Rows[0]["CTRLC3"].ToString().Trim();
                    string strFilePathPwd = dtSAPPath.Rows[0]["CTRLC4"].ToString().Trim();
                    Qci.Base.Common.FileAccess objFile = new FileAccess(strFileInPath_CSMC, strFilePathAccount, strFilePathPwd);

                    #endregion

                    //有幾個string類型的輸入參數這邊就宣告幾個ArrayList
                    ArrayList[] alStr = new ArrayList[0];
                    DataTable dtTemp = new DataTable();

                    //有幾備個ref table的輸入參數這邊就宣告幾個Array List
                    ArrayList[] alTable = new ArrayList[1];

                    alTable[0] = new ArrayList();
                    alTable[0].Add("ITABIN");
                    alTable[0].Add(dtData);

                    //產生文檔的檔名
                    strFileName = strFileHeader.Trim() + DateTime.Now.ToString("yyyyMMddHHmmss") + Guid.NewGuid().ToString().Substring(0, 4) + ".txt";

                    objLogData.AddQWMSLOG(dtData.Rows[0]["MBLNR"].ToString().Trim(), "SAP", "IN", "开始传入SAP扣帐", null, strFileName);
                    if (!objFile.WriteSapFile(alStr, alTable, strFileInPath_CSMC, strFileName, true))
                    {
                        Thread.Sleep(6000);
                    }
                    objLogData.AddQWMSLOG(dtData.Rows[0]["MBLNR"].ToString().Trim(), "SAP", "IN", "完成传入SAP扣帐", null, strFileName);

                    //讀取SAP的檔案
                    objLogData.AddQWMSLOG(dtData.Rows[0]["MBLNR"].ToString().Trim(), "SAP", "IN", "开始读取SAP扣帐结果", null, strFileName);

                    dtResponse = ReadSapFile_SapFile_CSMC_BP(strFileOutPath_CSMC, strFilePathAccount, strFilePathPwd, dtData.Rows[0]["MBLNR"].ToString().Trim(), varMTYPE);
                }
                catch (Exception ex)
                {
                    objLogData.AddQWMSLOG(dtData.Rows[0]["MBLNR"].ToString().Trim(), "SAP", "IN", "读取SAP扣帐结果异常", null,
                        strFileName + ":" + ex.Message);
                    //模拟回执
                    dtResponse.TableName = "SAP";
                    createDtResponse(varMTYPE, ref dtResponse);
                    DataRow dr = dtResponse.NewRow();
                    dr["MBLNR"] = dtData.Rows[0]["MBLNR"].ToString().Trim();
                    dr["RESULT"] = "";
                    dr["REMARK1"] = "读取SAP扣帐结果异常:" + ex.Message;
                    dr["REMARK2"] = "读取SAP扣帐结果异常:" + ex.Message;
                    dtResponse.Rows.Add(dr);
                }

                return dtResponse;
            }

            //与SAP交互(Read)
            public DataTable ReadSapFile_SapFile_CSMC_BP(string strFileOutPath_CSMC, string strFilePathAccount, string strFilePathPwd, string PalletId, string varMTYPE)
            {
                #region SAP PATH
                Qci.Base.Common.FileAccess objFile = new FileAccess(strFileOutPath_CSMC, strFilePathAccount, strFilePathPwd);
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);
                #endregion

                ArrayList aryString = new ArrayList();
                ArrayList aryTable = new ArrayList();
                ArrayList aryData = new ArrayList();
                DataTable dtReturn = new DataTable();

                aryString.Add("ERRORMSG");
                aryString.Add("STATUS");
                aryTable.Add("ITABIN");

                dtReturn.TableName = "SAP";
                createDtResponse(varMTYPE, ref dtReturn);

                try
                {
                    //檔案名稱只要輸入"abc"，即會抓取abc開頭的檔案進行解析
                    string strFileBackupPath = strFileOutPath_CSMC + @"\Backup"; //檔案輸出路徑
                    ArrayList[] aryReturn = null;
                    objLogData.AddQWMSLOG(PalletId, "SAP", "IN", "开始Check SAP 文档...", "", null);
                    if (CheckSAPDoc(strFileOutPath_CSMC, strFilePathAccount, strFilePathPwd, strFileName))
                    {
                        aryReturn = objFile.ReadSapFile(aryString, aryTable, strFileOutPath_CSMC, strFileName, 1000, 50000, strFileBackupPath);
                        objLogData.AddQWMSLOG(PalletId, "SAP", "IN", "结束Check SAP 文档", "有文档", null);
                    }
                    else
                    {
                        objLogData.AddQWMSLOG(PalletId, "SAP", "IN", "结束Check SAP 文档", "15s内未Check到文档 仍然执行读取文档", null);
                        aryReturn = objFile.ReadSapFile(aryString, aryTable, strFileOutPath_CSMC, strFileName, 1000, 50000, strFileBackupPath);
                    }

                    //此為table的回傳值
                    DataTable dtTemp = (DataTable)(aryReturn[2][1]);
                    LoadSAPDateToDtResponse(varMTYPE, ref dtReturn, dtTemp);

                    if (dtReturn.Rows.Count <= 0 || dtReturn == null)
                    {
                        AddWHTRSLOG("SAP", PalletId, strFileName, "T", "");
                    }
                    if (!string.IsNullOrEmpty(dtReturn.Rows[0]["REMARK2"].ToString().Trim()))
                    {
                        string[] GRtemp = dtReturn.Rows[0]["REMARK2"].ToString().Trim().Split(':');
                        //Modif By Michael 20150507 for 加强判断准确性
                        if (GRtemp.Length >= 2 && "49;50".Contains(GRtemp[1].Trim().Substring(0, 2)) &&
                            GRtemp[1].Trim().Length == 10 && !GRtemp[1].Trim().Contains("."))
                        {
                            AddWHTRSLOG("SAP", dtReturn.Rows[0]["MBLNR"].ToString(), strFileName, "Y", GRtemp[1].Trim());
                        }
                        else
                        {
                            AddWHTRSLOG("SAP", dtReturn.Rows[0]["MBLNR"].ToString(), strFileName, "N", dtReturn.Rows[0]["REMARK2"].ToString());
                        }
                    }
                    else
                    {
                        AddWHTRSLOG("SAP", dtReturn.Rows[0]["MBLNR"].ToString(), strFileName, "Y", dtReturn.Rows[0]["RESULT"].ToString().Trim());
                    }
                }

                catch (Exception ex)
                {
                    AddWHTRSLOG("SAP", PalletId, strFileName, "T", ex.Message);
                    DataRow dr = dtReturn.NewRow();
                    dr["MBLNR"] = PalletId;
                    dr["RESULT"] = "";
                    dr["REMARK1"] = "读取SAP文档失败:" + ex.Message;
                    dr["REMARK2"] = "读取SAP文档失败:" + ex.Message;
                    dtReturn.Rows.Add(dr);
                    ERRMSG = ex.Message;
                }

                return dtReturn;
            }

