            #region TransferStatusToQMS_BP

            public string[] TransferStatusToQMS_BP(string MBLNR, string StationName, string SapNo, string ReturnMessage, string OPType)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "TransferStatusToQMS_BP";
                this.ControlMethodParm = "(" + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                try
                {

                    #region CODE IS HERE

                    string[] message = { "", "" };
                    DataSet ds = new DataSet();
                    string strConnectionString = "";

                    strConnectionString = GetQMSDBconn(MBLNR);

                    SqlConnection db = new SqlConnection(strConnectionString);

                    try
                    {
                        SqlCommand cmd = new SqlCommand("spDelMaterial_ForQWMS_WHIN", db);
                        cmd.CommandType = CommandType.StoredProcedure;
                        cmd.Parameters.Add("@PalletID", SqlDbType.VarChar, 50);
                        cmd.Parameters["@PalletID"].Value = MBLNR;

                        cmd.Parameters.Add("@StationType", SqlDbType.VarChar, 10);
                        cmd.Parameters["@StationType"].Value = StationName;

                        cmd.Parameters.Add("@SapNo", SqlDbType.VarChar, 50);
                        cmd.Parameters["@SapNo"].Value = SapNo;

                        cmd.Parameters.Add("@ReturnMessage", SqlDbType.VarChar, 100);
                        cmd.Parameters["@ReturnMessage"].Value = ReturnMessage;

                        cmd.Parameters.Add("@OPType", SqlDbType.VarChar, 10);
                        cmd.Parameters["@OPType"].Value = OPType;

                        db.Open();

                        SqlDataAdapter da = new SqlDataAdapter();
                        da.SelectCommand = cmd;
                        da.Fill(ds);
                        message[0] = ds.Tables[0].Rows[0][0].ToString();
                        message[1] = ds.Tables[0].Rows[0][1].ToString();
                        AddWHTRSLOG("QMS", MBLNR, "spDelMaterial_ForQWMS_WHIN", message[0].ToString().Trim().Equals("Pass", StringComparison.CurrentCultureIgnoreCase) == true ? "Y" : "T", message[0] + ":" + message[1]);
                    }
                    catch (Exception ex)
                    {
                        AddWHTRSLOG("QMS", MBLNR, "spDelMaterial_ForQWMS_WHIN", "T", ex.Message);
                        throw ex;
                    }
                    finally
                    {
                        db.Close();
                    }

                    return message;

                    #endregion
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                } //可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

