            public bool QueryDataExistsInStoragebySplit(string strLocat, string strMatnr, string strInsmk, string strMblnr, string strCharg)
            {

                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QueryDataExistsInStorage";
                this.ControlMethodParm = "(" + strLocat + "," + strMatnr + "," + strInsmk + "," + strMblnr + "," + strCharg + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                DataWhitm objWhitm = new DataWhitm(UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alQueryConditions = new ArrayList();

                alColumns.Add("*");

                alQueryConditions.Add("MANDT = '" + UserData.Client + "'");
                alQueryConditions.Add("COMCD = '" + UserData.CompanyCode + "'");
                alQueryConditions.Add("WERKS = '" + WERKS + "'");
                alQueryConditions.Add("LGORT = '" + LGORT + "'");
                alQueryConditions.Add("LOCAT = '" + strLocat + "'");
                alQueryConditions.Add("MATNR = '" + strMatnr + "'");
                alQueryConditions.Add("MBLNR = '" + strMblnr + "'");
                alQueryConditions.Add("INSMK = '" + strInsmk + "'");
                alQueryConditions.Add("CHARG = '" + strCharg + "'");

                DataTable dtData = new DataTable();
                try
                {
                    //ControlHandleDB();

                    dtData = objWhitm.EntityQuery(alColumns, alQueryConditions, false, true);
                    //ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                if (dtData.Rows.Count > 0)
                {
                    return true;
                }
                else
                {
                    return false;
                }
            }


