            //strWerks,strLgort,strMatnr,strLifnr
            public DataTable GetStorageByMatnrLifnr(string strWerks, string strLgort, string strMatnr, string strLifnr, bool bolNotVenCode)
            {
                DataTable dtData = new DataTable();
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(UserData);
                try
                {
                    string strSQL = "";
                    //strSQL = "SELECT  MANDT,WERKS,LGORT,MATNR,LIFNR,SUM(MENGE - OTQTY)AS MENGE FROM WHDWN WITH(NOLOCK) WHERE  MTYPE='SAP'  AND  ( ( TRNTP='G+'  AND BWART='321'  ) OR  ( TRNTP='T+'  AND BWART ='311'  ) )   AND  (MENGE- OTQTY)>0  "
                    //    + " AND  MANDT='" + MANDT + "' AND WERKS='" + strWerks + "' AND LGORT='" + strLgort + "'  AND MATNR ='" + strMatnr + "'  ";//AND LIFNR='" + strLifnr + "' 
                    strSQL = "SELECT  D.MANDT,D.WERKS,D.LGORT,D.MATNR,D.LIFNR,SUM(D.MENGE - D.OTQTY)AS MENGE FROM WHDWN D WITH(NOLOCK) LEFT JOIN EC_INSTOCK E WITH(NOLOCK) ON E.MANDT=D.MANDT AND E.COMCD=D.COMCD AND E.WERKS=D.WERKS AND E.LGORT=D.LGORT AND E.MBLNR=SUBSTRING(D.GRLNR,1,10)   WHERE  D.MTYPE='SAP'  AND  ( ( D.TRNTP='G+'  AND D.BWART='321'  ) OR  ( D.TRNTP='T+'  AND D.BWART ='311'  ) )   AND  (D.MENGE- D.OTQTY)>0    AND    "
                        + "  D.MANDT='" + MANDT + "' AND D.WERKS='" + strWerks + "' AND D.LGORT='" + strLgort + "'  AND D.MATNR ='" + strMatnr + "'  AND (E.MBLNR IS NULL OR E.MBLNR='')";
                    //新增 315 351 10S
                    if (!bolNotVenCode)
                    {
                        strSQL = "SELECT  D.MANDT,D.WERKS,D.LGORT,D.MATNR,D.LIFNR,SUM(D.MENGE - D.OTQTY)AS MENGE FROM WHDWN D WITH(NOLOCK) LEFT JOIN EC_INSTOCK E WITH(NOLOCK) ON E.MANDT=D.MANDT AND E.COMCD=D.COMCD AND E.WERKS=D.WERKS AND E.LGORT=D.LGORT AND E.MBLNR=SUBSTRING(D.GRLNR,1,10)   WHERE  D.MTYPE='SAP'  AND  ( ( D.TRNTP='G+'  AND D.BWART='321'  ) OR  ( D.TRNTP='T+'  AND D.BWART ='311'  )OR  ( D.TRNTP='T+'  AND D.BWART ='315'  )OR ( D.TRNTP='T+'  AND D.BWART='351' ) OR ( D.TRNTP='T+'  AND D.BWART='10S' ) OR ( D.TRNTP='T+'  AND D.BWART ='350') OR ( D.TRNTP='T+'  AND D.BWART ='324') OR ( D.TRNTP='T+'  AND D.BWART ='344') )   AND  (D.MENGE- D.OTQTY)>0    AND    "
    + "  D.MANDT='" + MANDT + "' AND D.WERKS='" + strWerks + "' AND D.LGORT='" + strLgort + "'  AND D.MATNR ='" + strMatnr + "'  AND (E.MBLNR IS NULL OR E.MBLNR='')";
                    }


                    if ((!objStorageData.CheckStorageInType(strWerks, strLgort, "Diff Vendor Diff Locat") && bolNotVenCode))
                    {
                        strSQL += " AND D.LIFNR='" + strLifnr + "'   ";
                    }
                    strSQL += " GROUP BY  D.MANDT,D.WERKS,D.LGORT,D.MATNR,D.LIFNR  ";
                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL.ToString());
                    ControlSqlAccess.CloseConnection();

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- GetStorageByMatnrLifnr()";
                }
                return dtData;
            }

            public DataTable QuerySapLineInData_DateCode(string strMatnr, string strLifnr, string strLocat, string strIndat, string strVedat, string strDaCod, string strLocod, bool bolNotVenCode,string strExpdate,string strTASKID, string strSerno)
            {
                DataTable dtData = new DataTable();
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(UserData);
                try
                {
                    string strSQL = "";
                    strSQL = "SELECT DISTINCT * FROM (SELECT  TOP 100 PERCENT " 
                                   + " (CASE WHEN ISNULL(I.EXPDAT_AFTER,'') = '' THEN D.ExpiryDate ELSE I.EXPDAT_AFTER END) AS ExpiryDate,"
                                   + " (CASE WHEN ISNULL(I.MAXEXP,'')='' THEN '' ELSE (CASE WHEN ISNULL(I.MAXEXP_AFTER,'')='' THEN I.MAXEXP ELSE I.MAXEXP_AFTER END) END) AS MAXEXP,"
                                   + " (CASE WHEN ISNULL(I.TASKID,'')='' THEN '' ELSE I.TASKID END) AS TASKID,"
                                   + " I.RMAK1 AS IQCRMAK1,D.MANDT, D.COMCD,D.WERKS, D.LGORT, '" + strLocat + "' as LOCAT,  D.MATNR, D.INSMK, D.CHARG, (D.MENGE - D.OTQTY) AS MENGE, 0 as ALQTY,  D.MBLNR, D.ZEILE,D.EBELN, "
                                   + " '" + strLifnr + "' AS LIFNR  ,'' as OMBLNR, "
                                   + " '' as MRGID, D.KOSTL,D.ARBPL,D.TRNTP, ISNULL(D.REMAK1,'')  AS RMAK1, '" + strIndat + "' as INDAT,'" + strVedat + "'  AS   VEDAT ,ISNULL (D.KDMAT,'')  AS KDMAT, "
                                   + " '" + strSerno + "' AS SERNO,'" + strLocod + "' AS 'LOCOD' , D.INSPT ,  '" + strDaCod + "' AS DACOD  "
                                   + " from WHDWN D with (nolock)  "
                                   + " LEFT JOIN WHIQC I WITH(NOLOCK) ON I.TASKID='"+ strTASKID + "' AND I.EXPDAT_AFTER='"+ strExpdate + "'"
                                   + " LEFT JOIN EC_INSTOCK E WITH(NOLOCK)  ON E.MANDT=D.MANDT AND E.COMCD=D.COMCD AND E.WERKS=D.WERKS AND E.LGORT=D.LGORT AND E.MBLNR=SUBSTRING(D.GRLNR,1,10)"
                                   + " WHERE D.MTYPE='SAP'   AND (D.MENGE- D.OTQTY)>0  ";

                    if (WERKS == "CS12" && LGORT == "TW52")
                    {
                        strSQL = strSQL + " AND ( D.TRNTP='G+' AND D.BWART='321' ) ";
                    }
                    if (!bolNotVenCode)
                    {
                        strSQL += " AND  ( ( D.TRNTP='G+' AND D.BWART='321' ) OR  ( D.TRNTP='T+'  AND D.BWART='311' ) OR  ( D.TRNTP='T+'  AND D.BWART='315' )OR ( D.TRNTP='T+'  AND D.BWART='351' ) OR ( D.TRNTP='T+'  AND D.BWART='10S' ) OR  ( D.TRNTP='T+'  AND D.BWART='350' ) OR  ( D.TRNTP='T+'  AND D.BWART='325' )OR  ( D.TRNTP='T+'  AND D.BWART='344' ) )  ";
                    }
                    else
                    {
                        strSQL = strSQL + " AND  ( ( D.TRNTP='G+' AND D.BWART='321' ) OR  ( D.TRNTP='T+'  AND D.BWART='311' )  )";                   
                    }     
                        
                    strSQL = strSQL + "  AND  D.MANDT='" + MANDT + "' AND D.COMCD='" + COMCD + "' AND D.WERKS='" + WERKS + "' AND D.LGORT='" + LGORT + "' AND D.MATNR='" + strMatnr + "'  "
                                  + " AND (E.MBLNR IS NULL OR E.MBLNR='')";

                    if (!objStorageData.CheckStorageInType(strWerks, strLgort, "Diff Vendor Diff Locat") && bolNotVenCode)
                    {
                        strSQL += " AND D.LIFNR='" + strLifnr + "'   ";
                    }
                    strSQL += "   ORDER BY D.CRDAT) A ";

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL.ToString());
                    ControlSqlAccess.CloseConnection();

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- QuerySapLineInData_DateCode()";
                }
                return dtData;
            }


            public DataTable QuerySapLineInData_AGV(string strMatnr, string strLifnr, string strLocat, string strIndat, string strVedat, string strDaCod, string strLocod, bool bolNotVenCode, string strExpdate, string strTASKID)
            {
                DataTable dtData = new DataTable();
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(UserData);
                try
                {
                    string strSQL = "";
                    strSQL = "SELECT DISTINCT * FROM (SELECT  TOP 100 PERCENT "
                                   + " (CASE WHEN ISNULL(I.EXPDAT_AFTER,'') = '' THEN D.ExpiryDate ELSE I.EXPDAT_AFTER END) AS ExpiryDate,"
                                   + " (CASE WHEN ISNULL(I.MAXEXP,'')='' THEN '' ELSE (CASE WHEN ISNULL(I.MAXEXP_AFTER,'')='' THEN I.MAXEXP ELSE I.MAXEXP_AFTER END) END) AS MAXEXP,"
                                   + " (CASE WHEN ISNULL(I.TASKID,'')='' THEN '' ELSE I.TASKID END) AS TASKID,"
                                   + " I.RMAK1 AS IQCRMAK1,D.MANDT, D.COMCD,D.WERKS, D.LGORT, '" + strLocat + "' as LOCAT,  D.MATNR, D.INSMK, D.CHARG, (D.MENGE - D.OTQTY) AS MENGE, 0 as ALQTY,  D.MBLNR, D.ZEILE,D.EBELN, "
                                   + " '" + strLifnr + "' AS LIFNR  ,'' as OMBLNR, "
                                   + " '' as MRGID, D.KOSTL,D.ARBPL,D.TRNTP, ISNULL(D.REMAK1,'')  AS RMAK1, '" + strIndat + "' as INDAT,'" + strVedat + "'  AS   VEDAT ,ISNULL (D.KDMAT,'')  AS KDMAT, "
                                   + " ISNULL(D.SERNO,'') AS SERNO,'" + strLocod + "' AS 'LOCOD' , D.INSPT ,  '" + strDaCod + "' AS DACOD  "
                                   + " from WHDWN D with (nolock)  "
                                   + " LEFT JOIN WHIQC I WITH(NOLOCK) ON I.TASKID='" + strTASKID + "' AND I.EXPDAT_AFTER='" + strExpdate + "'"
                                   + " WHERE D.MTYPE='SAP'   AND (D.MENGE- D.OTQTY)>0  ";
                    if (!bolNotVenCode)
                    {
                        strSQL += " AND  ( ( D.TRNTP='G+' AND D.BWART='321' ) OR  ( D.TRNTP='T+'  AND D.BWART='311' ) OR  ( D.TRNTP='T+'  AND D.BWART='315' )OR ( D.TRNTP='T+'  AND D.BWART='351' ) OR ( D.TRNTP='T+'  AND D.BWART='10S' ) OR  ( D.TRNTP='T+'  AND D.BWART='350' ) OR  ( D.TRNTP='T+'  AND D.BWART='325' )OR  ( D.TRNTP='T+'  AND D.BWART='344' ) OR ( D.TRNTP='G+' AND D.BWART='101' ) OR ( D.TRNTP='G+' AND D.BWART='10S' ))  ";
                    }
                    else
                    {
                        strSQL = strSQL + " AND  ( ( D.TRNTP='G+' AND D.BWART='321' ) OR  ( D.TRNTP='T+'  AND D.BWART='311' ) OR ( D.TRNTP='G+' AND D.BWART='101' ) OR ( D.TRNTP='G+' AND D.BWART='10S' ) )";
                    }

                    strSQL = strSQL + "  AND  D.MANDT='" + MANDT + "' AND D.COMCD='" + COMCD + "' AND D.WERKS='" + WERKS + "' AND D.LGORT='" + LGORT + "' AND D.MATNR='" + strMatnr + "' AND D.INSMK='G' ";
