            #region PCBA退库 入库
            public bool AddGBOnLineInData_PCBA(string strWerks, string strLgort, string strLocat, DataTable dtStorage, ArrayList arrBoxID, DataTable dtNoneCombine, string strMethods)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddGBOnLineInData_PCBA";
                this.ControlMethodParm = "(" + strLocat + "," + dtStorage + "," + arrBoxID + "," + dtNoneCombine + "," + strMethods + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                #region 變數宣告
                string strTemp = "";
                string strSQL = "";
                string strTempLocat = "";

                DataWhhed objWhhed = new DataWhhed(UserData);
                DataWhitm objWhitm = new DataWhitm(UserData);
                DataWhbox objWhbox = new DataWhbox(UserData);
                DataWhdwn objWhdwn = new DataWhdwn(UserData);

                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                StringBuilder sbSql = new StringBuilder();
                ArrayList arySQL = new ArrayList();
                ArrayList aryCheckSQL = new ArrayList();
                ArrayList aryCheckList = new ArrayList();
                StringBuilder sbCheckList = new StringBuilder();
                ArrayList arySQL1 = new ArrayList();
                ArrayList aryLocat = new ArrayList();
                #endregion

                #region WHLOG
                QCI.QWMS.LogData objLogData = new QCI.QWMS.LogData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT, strProgid);
                arySQL = objLogData.AddLogData("", "", dtStorage);
                #endregion

                //if (strMethods == "UNFATP")
                //{
                //    //BGM类型的不入实际库存，只要记录SN即可
                //    strLocat = "BGM";
                //}

                //if (strMethods == "FATP")
                //{
                #region WHITM
                QCI.QWMS.StorageData objStorageData = new QCI.QWMS.StorageData(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData, WERKS, LGORT);
                for (int i = 0; i < dtStorage.Rows.Count; i++)
                {
                    if (strTempLocat.IndexOf(dtStorage.Rows[i]["LOCAT"].ToString()) < 0)
                    {
                        aryLocat.Add(dtStorage.Rows[i]["LOCAT"].ToString());
                        strTempLocat += "++" + dtStorage.Rows[i]["LOCAT"].ToString();
                    }
                    //HAC
                    if (!objStorageData.QueryDataExistsInStorage(dtStorage.Rows[i]["LOCAT"].ToString(), dtStorage.Rows[i]["MATNR"].ToString(), dtStorage.Rows[i]["INSMK"].ToString(), "GB", dtStorage.Rows[i]["CHARG"].ToString(), dtStorage.Rows[i]["SERNO"].ToString(), "", ""))
                    {

                        strSQL = " Insert Into DBO.WHITM (MANDT , COMCD , WERKS , LGORT , LOCAT , MATNR ,CHARG , INSMK ,MBLNR , LIFNR , EBELN , INDAT , MENGE , QCQTY , REFNO , "
                                    + " 	MRGID , ISPTM , RMAK1 , CRNAM , CRDAT , MONAM , MODAT ) "
                                    + "  Values ('" + MANDT + "','" + COMCD + "','" + strWerks + "','" + strLgort + "','" + strLocat + "','" + dtStorage.Rows[i]["MATNR"].ToString() + "','" + dtStorage.Rows[i]["CHARG"].ToString() + "','" + dtStorage.Rows[i]["INSMK"].ToString() + "','" + dtStorage.Rows[i]["MBLNR"].ToString() + "', "

                                     + "  '" + dtStorage.Rows[i]["LIFNR"].ToString() + "' ,'', '" + dtStorage.Rows[i]["INDAT"].ToString() + "','" + dtStorage.Rows[i]["MENGE"].ToString() + "',0,'','','','','" + UserData.UserId + "',GETDATE(),'" + UserData.UserId + "',GETDATE())  ";

                        arySQL.Add(strSQL);
                    }
                    else
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objWhitm.ResetField();

                        objWhitm.Menge = "MENGE +" + dtStorage.Rows[i]["ALQTY"].ToString();
                        objWhitm.Rmak1 = dtStorage.Rows[i]["RMAK1"].ToString();
                        objWhitm.Monam = CRNAM;
                        objWhitm.Modat = "GetDate()";
                        alConditions.Add("Mandt= '" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                        alConditions.Add("Comcd= '" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                        alConditions.Add("Werks= '" + dtStorage.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add("Lgort= '" + dtStorage.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add("Locat= '" + dtStorage.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add("Matnr= '" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add("Insmk= '" + dtStorage.Rows[i]["INSMK"].ToString() + "'");
                        alConditions.Add("Mblnr= 'GB'");
                        alConditions.Add("Charg= '" + dtStorage.Rows[i]["CHARG"].ToString() + "'");
                        alConditions.Add("Serno= '" + dtStorage.Rows[i]["SERNO"].ToString() + "'");

                        strSQL = objWhitm.EntityGetUpdateSql(alConditions);
                        arySQL.Add(strSQL);
                    }
                }
                #endregion

                #region WHDWN
                alColumns.Clear();
                alConditions.Clear();
                objWhdwn.ResetField();
                alColumns.Add(" MBLNR + '--' + ZEILE ");
                alConditions.Add("(MANDT= '" + MANDT + "')");
                alConditions.Add("(COMCD= '" + COMCD + "')");
                alConditions.Add("(MBLNR= '" + dtNoneCombine.Rows[0]["MBLNR"].ToString() + "')");

                alConditions.Add("(MENGE < OTQTY+ " + dtNoneCombine.Rows[0]["ALQTY"].ToString() + ")");
                strTemp = "";
                strTemp = objWhdwn.EntityGetQuerySql(alColumns, alConditions, false, true);
                aryCheckSQL.Add(strTemp);
                #endregion

                #region "Update WHHED Table"
                for (int i = 0; i < aryLocat.Count; i++)
                {
                    sbSql.Remove(0, sbSql.Length);
                    sbSql.Append("Update WHHED set  ");
                    sbSql.AppendFormat("  LOSTS=T.TOTAL from ");
                    sbSql.AppendFormat(" (Select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm WITH (NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + strWerks + "' and LGORT= '" + strLgort + "' and LOCAT= '" + aryLocat[i].ToString() + "') as T  ");
                    sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    sbSql.AppendFormat(" and WERKS='{0}' ", strWerks);
                    sbSql.AppendFormat(" and LGORT='{0}' ", strLgort);
                    sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocat[i].ToString());
                    arySQL.Add(sbSql.ToString());

                    //sbSql.Remove(0, sbSql.Length);
                    //sbSql.Append("Update WHHED set  ");
                    //sbSql.AppendFormat("  ISMRG=T.ISMRG from ");
                    //sbSql.AppendFormat(" (Select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm WITH (NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + strWerks + "' and LGORT= '" + strLgort + "' and LOCAT= '" + aryLocat[i].ToString() + "' and MRGID<>'') as T  ");
                    //sbSql.AppendFormat(" Where MANDT='{0}' ", MANDT);
                    //sbSql.AppendFormat(" and COMCD='{0}' ", COMCD);
                    //sbSql.AppendFormat(" and WERKS='{0}' ", strWerks);
                    //sbSql.AppendFormat(" and LGORT='{0}' ", strLgort);
                    //sbSql.AppendFormat(" and LOCAT='{0}' ", aryLocat[i].ToString());
                    //arySQL.Add(sbSql.ToString());
                }
                #endregion
                //}

                #region 更新入库状态WHDWN
                sbSql.Remove(0, sbSql.Length);
                sbSql.AppendFormat(" UPDATE WHDWN SET  OTQTY = MENGE WHERE MANDT ='218'AND MTYPE IN ( 'QMS_BGM','QMS_FAT' ) AND MBLNR='{0}'  AND COMCD='" + COMCD + "'", dtNoneCombine.Rows[0]["MBLNR"].ToString());
                arySQL.Add(sbSql.ToString());

                #endregion

                #region WHBOX
                StringBuilder strsqlbox = new StringBuilder();
                strsqlbox.AppendFormat(" INSERT INTO WHBOX (MANDT,COMCD,WERKS,LGORT,LOCAT,MBLNR,BOXID,INSMK,CHARG,MATNR,SERNO,LOADID,KDMAT,MENGE,CRTDAT) ");
                strsqlbox.AppendFormat(" SELECT MANDT,COMCD,WERKS,LGORT,'" + strLocat + "' as LOCAT,MBLNR,BOXID,INSMK,CHARG,MATNR,SERNO,LOADID,KDMAT,MENGE,GETDATE()  ");
                strsqlbox.AppendFormat(" FROM WHDWN WITH (NOLOCK) WHERE MANDT ='218' AND MTYPE IN ('QMS_BGM','QMS_FAT')   AND  MBLNR='" + dtNoneCombine.Rows[0]["MBLNR"].ToString() + "'");
                arySQL.Add(strsqlbox.ToString());
                #endregion


                bool bolReturn = false;
                try
                {
                    if (aryCheckList.Count <= 0)
                    {
                        StringBuilder alSQL = new StringBuilder();
                        for (int i = 0; i < arySQL.Count; i++)
                        {
                            alSQL.AppendLine(" " + arySQL[i].ToString() + "");
                        }
                        ControlHandleDB();
                        bolReturn = ControlSqlAccess.ExecSql(alSQL.ToString());
                        ControlSqlAccess.CloseConnection();
                    }
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
                return bolReturn;
            }

