            #region 根据ReferenceID带出同一个ReferenceID的所有单证 by Annie 20171227
            public DataTable GetAllDatabyReferenceID(string varWerks, string varLgort, string strLocat, string varReferenceID, string strSANo, string strDacod, string strVedat)
            {
                DataTable dtData = new DataTable();

                try
                {
                    string strSQL = string.Empty;
                    if (string.IsNullOrEmpty(strSANo) && string.IsNullOrEmpty(strDacod) && string.IsNullOrEmpty(strVedat))
                    {
                        strSQL = " select  'false' as Cselect, MANDT,COMCD, MTYPE, WERKS, LGORT,  MBLNR,ZEILE ,BOXID,'" + strLocat + "'  AS LOCAT,MATNR,CHARG,MENGE,INSMK,"
                        + "   SERNO,LIFNR,EBELN,CONVERT(VARCHAR(20),getdate(),112)AS INDAT,REMAK1,MENGE  AS ALQTY ,KOSTL,ARBPL,'' AS MRGID,TRNTP,0 AS SCANQTY,CONVERT(VARCHAR(20),getdate(),112)AS MCDAT,'' AS DACOD "
                        + " from [dbo].[WHDWN] where  MTYPE IN ('BPM_TIC','OA_TIC','SAP_TIC')  AND  WERKS='" + varWerks + "'and LGORT='" + varLgort + "'and MBLNR='" + varReferenceID + "'  AND ISNULL(REMAK1,'')='' AND ( MENGE>OTQTY OR OTQTY=0)";
                    }
                    else if (string.IsNullOrEmpty(strSANo) && !string.IsNullOrEmpty(strDacod) && !string.IsNullOrEmpty(strVedat))
                    {
                        strSQL = " select DISTINCT  'false' as Cselect, D.MANDT,D.COMCD, D.MTYPE, D.WERKS, D.LGORT,  D.MBLNR,D.ZEILE ,C.BOXID,'" + strLocat + "'  AS LOCAT,D.MATNR,D.CHARG,C.MENGE,D.INSMK,"
                        + "   D.SERNO,D.LIFNR,D.EBELN,CONVERT(VARCHAR(20),getdate(),112)AS INDAT,D.REMAK1,C.MENGE  AS ALQTY ,D.KOSTL,D.ARBPL,'' AS MRGID,D.TRNTP,0 AS SCANQTY,CONVERT(VARCHAR(20),getdate(),112)AS MCDAT,C.DACOD AS DACOD, C.VEDAT AS VEDAT "
                        + " from [dbo].[WHDWN] D INNER JOIN [dbo].[WHTIC] C ON D.WERKS=C.WERKS AND D.LGORT=C.LGORT AND D.MBLNR=C.MBLNR AND D.MATNR=C.MATNR AND D.BOXID=C.REMAK1 where  D.MTYPE IN ('BPM_TIC','OA_TIC','SAP_TIC')  AND"
                        +  " D.WERKS='" + varWerks + "'and D.LGORT='" + varLgort + "'and D.MBLNR='" + varReferenceID + "'  AND ISNULL(D.REMAK1,'')='' AND ( D.MENGE>D.OTQTY OR D.OTQTY=0) AND C.PRCDE=0";
                    }
                    else
                    {
                        strSQL = " select  'false' as Cselect,MANDT,COMCD,MTYPE, WERKS, LGORT,  MBLNR,ZEILE ,BOXID,'" + strLocat + "'  AS LOCAT,MATNR,CHARG,MENGE,INSMK,SERNO,LIFNR,EBELN,"
                        + "  CONVERT(VARCHAR(20),getdate(),112)AS INDAT,REMAK1,MENGE  AS ALQTY ,KOSTL,ARBPL,'' AS MRGID,TRNTP ,0 AS SCANQTY,CONVERT(VARCHAR(20),getdate(),112)AS MCDAT ,'' AS DACOD"
                        + "  from [dbo].[WHDWN] where  MTYPE IN ('BPM_TIC','OA_TIC','SAP_TIC')  AND WERKS='" + varWerks + "' and LGORT='" + varLgort + "'and LOADID='" + strSANo + "' AND ISNULL(REMAK1,'')='' AND ( MENGE>OTQTY OR OTQTY=0)";
                    }


                    dtData = ControlSqlAccess.GetDataTable(strSQL.ToString());
                    ControlSqlAccess.CloseConnection();

                }
                catch (System.Exception ex)
                {
                    ERRMSG = ex.Message + "<- GetAllDatabyReferenceID()";
                }
                return dtData;
            }

