            #region 获取EC单扣帐记录
            public DataTable GetPacingInfo(string werks, string lgort, string scan, string begintime, string endtime, string ECNo, string custid)
            {

                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "GetPacingInfo";
                this.ControlMethodParm = "(" + ECNo + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                StringBuilder strsql = new StringBuilder();

                strsql.AppendFormat("SELECT DISTINCT H.WERKS,H.LGORT,H.PNUM,CASE CLRTYP WHEN 'A' THEN N'逐票报关' ELSE N'汇总报关' END AS CLRTYP,CASE ISNULL(STATUS,'N') WHEN 'Y' THEN N'已扣帐' ELSE N'未扣帐' END AS STATUS ,CASE ISNULL(SCANBOX,'N') WHEN 'Y' THEN N'扫描Boxid入库' ELSE N'未扫描Boxid入库' END AS SCANBOX  ,H.CUSTID,(SELECT TOP 1 SGTXT FROM  EC_ITEM WITH(NOLOCK) WHERE PNUM=H.PNUM) AS SGTXT,I.BELNR,H.UPTIME FROM EC_HEAD  AS H WITH(NOLOCK) INNER JOIN EC_ITEM AS I  WITH(NOLOCK) ON H.PNUM=I.PNUM where H.UPTIME BETWEEN CONVERT(VARCHAR(10),convert(datetime,'{0}'),120)+' 00:00:00' AND CONVERT(VARCHAR(10),convert(datetime,'{1}'),120)+' 23:59:59'", begintime, endtime);
                if (werks != "")
                {
                    strsql.AppendFormat(" and H.WERKS='{0}'", werks);
                }
                if (lgort != "")
                {
                    strsql.AppendFormat(" and I.lgort='{0}'", lgort);
                }

                if (scan != "")
                {
                    strsql.AppendFormat(" and H.scan='{0}'", scan);
                }

                if (ECNo != "")
                {
                    strsql.AppendFormat(" and H.PNUM='{0}'", ECNo);
                }

                if (custid != "")
                {
                    strsql.AppendFormat(" and RIGHT( H.custid,9)='{0}'", custid);
                }


                DataTable dtData = new DataTable();
                try
                {
                    ControlHandleDB();

                    dtData = ControlSqlAccess.GetDataTable(strsql.ToString());
                    ControlSqlAccess.CloseConnection();
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return dtData;
            }

