            public bool AddSNData(DataTable dtCombine)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "AddSNData";
                this.ControlMethodParm = "('')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }


                try
                {
                    ArrayList arySQL = new ArrayList();
                    ArrayList aryLocat = new ArrayList();
                    LogData objLogData = new LogData(UserData, WERKS, LGORT, PROGID);
                    MixedMaterial objMixed = new MixedMaterial(UserData, WERKS);
                    StorageData objStorage = new StorageData(UserData, WERKS, LGORT);
                    DataWhbox objDataWhbox = new DataWhbox(UserData);
                    ArrayList alColumns = new ArrayList();
                    ArrayList alConditions = new ArrayList();
                    StringBuilder sbSql = new StringBuilder();
                    DataWhbox objWhbox = new DataWhbox(UserData);
                    string strSQL;

                    arySQL = objLogData.AddLogSNTOQMSData(dtCombine);


                    for (int i = 0; i < dtCombine.Rows.Count; i++)
                    {

                        strSQL = "Insert into WHOUT(MANDT, COMCD, WERKS, LGORT, LOCAT, UMLGO,MBLNR,BOXID,CHARG, MATNR,SERNO,FLAGE,CRNAM,CRDAT ) " +
                           "values('" + dtCombine.Rows[i]["MANDT"].ToString() + "', '" + dtCombine.Rows[i]["COMCD"].ToString() + "', '" + dtCombine.Rows[i]["WERKS"].ToString() + "','" + dtCombine.Rows[i]["LGORT"].ToString() + "','" +
                           dtCombine.Rows[i]["LOCAT"].ToString() + "','','" + dtCombine.Rows[i]["MBLNR"].ToString() + "','" + dtCombine.Rows[i]["BOXID"].ToString() + "','" +
                           dtCombine.Rows[i]["CHARG"].ToString() + "','" + dtCombine.Rows[i]["MATNR"].ToString() + "','" + dtCombine.Rows[i]["SERNO"].ToString() + "','N','" + CRNAM + "',getdate())";
                        arySQL.Add(strSQL);

                        #region delete WHBOX表中的boxid和sn
                        alConditions.Clear();
                        alConditions.Add("MANDT='" + dtCombine.Rows[i]["MANDT"].ToString() + "'");
                        alConditions.Add("COMCD='" + dtCombine.Rows[i]["COMCD"].ToString() + "'");
                        alConditions.Add("WERKS='" + dtCombine.Rows[i]["WERKS"].ToString() + "'");
                        alConditions.Add("LGORT='" + dtCombine.Rows[i]["LGORT"].ToString() + "'");
                        alConditions.Add("LOCAT='" + dtCombine.Rows[i]["LOCAT"].ToString() + "'");
                        alConditions.Add("MATNR='" + dtCombine.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add("BOXID='" + dtCombine.Rows[i]["BOXID"].ToString() + "'");
                        alConditions.Add("MBLNR='" + dtCombine.Rows[i]["MBLNR"].ToString() + "'");
                        alConditions.Add("CHARG='" + dtCombine.Rows[i]["CHARG"].ToString() + "'");
                        alConditions.Add("SERNO='" + dtCombine.Rows[i]["SERNO"].ToString() + "'");
                        arySQL.Add(objDataWhbox.EntityGetDeleteSql(alConditions));
                        #endregion

                    }

                    bool bolReturn = false;
                    ControlHandleDB();
                    bolReturn = ControlSqlAccess.ExecSqlArray(arySQL);
                    ControlSqlAccess.CloseConnection();
                    return bolReturn;

                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }

