                    strSql.AppendFormat(" INSERT INTO WHLOG(MANDT,WERKS,LGORT,CGCLS,OLOCA,MATNR,CHARG,LIFNR,MBLNR,MENGE,INSMK,INDAT,CRNAM,CRDAT,COMCD,TRNTP) ");
                    strSql.AppendFormat(" 	VALUES('" + MANDT + "','" + dr["WERKS"].ToString() + "','" + dr["LGORT"].ToString() + "','" + PROGID + "','" + dr["LOCAT"].ToString() + "','" + dr["MATNR"].ToString() + "','" + dr["CHARG"].ToString() + "','" + dr["LIFNR"].ToString() + "','" + dr["MBLNR"].ToString() + "','" + dr["MENGE"].ToString() + "','" + dr["INSMK"].ToString() + "',CONVERT(varchar(8),GETDATE(),112),'" + UserData.UserId + "',GETDATE(),'" + COMCD + "','" + dr["INSMK"].ToString() + "+" + "') ");
                }
                #endregion

                #region WHTIC
                foreach (DataRow dr in dtData.Rows)
                {
                    strSql.AppendFormat(" UPDATE WHTIC SET OTQTY=MENGE,MODAT=GETDATE() WHERE MTYPE IN('SAP_IQC','OA_IQC') AND WERKS='{0}' AND LGORT='{1}' AND BOXID='{2}' ", dr["WERKS"].ToString(), dr["LGORT"].ToString(), dr["MBLNR"].ToString());
                }
