                foreach (DataRow dr in dtData.Rows)
                {
                    strSql.AppendFormat(" INSERT INTO WHITM(MANDT,WERKS,LGORT,LOCAT,MATNR,INSMK,MBLNR,CHARG,LIFNR,INDAT,MENGE,CRNAM,CRDAT,MONAM,MODAT,COMCD) ");
                    strSql.AppendFormat(" VALUES('" + MANDT + "','" + dr["WERKS"].ToString() + "','" + dr["LGORT"].ToString() + "','" + dr["LOCAT"].ToString() + "','" + dr["MATNR"].ToString() + "','" + dr["INSMK"].ToString() + "','" + dr["MBLNR"].ToString() + "','" + dr["CHARG"].ToString() + "','" + dr["LIFNR"].ToString() + "',CONVERT(varchar(8),GETDATE(),112),'" + dr["MENGE"].ToString() + "','" + UserData.UserId + "',GETDATE(),'" + UserData.UserId + "',GETDATE(),'" + COMCD + "') ");
                }
                #endregion

                #region WHHED
                foreach (DataRow dr in dtData.Rows)
                {
                    strSql.AppendFormat(" update WHHED set  LOSTS=T.TOTAL from (select TOTAL=case when count(*)>0 then '1' else '0' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + dr["WERKS"].ToString() + "' and LGORT= '" + dr["LGORT"].ToString() + "' and LOCAT= '" + dr["LOCAT"].ToString() + "') as T where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "' and WERKS= '" + dr["WERKS"].ToString() + "' and LGORT= '" + dr["LGORT"].ToString() + "' and LOCAT= '" + dr["LOCAT"].ToString() + "'");
                    //strSql.AppendFormat(" update WHHED set  ISMRG=T.ISMRG from (select ISMRG=case when count(*)>0 then 'Y' else 'N' end  from whitm WITH(NOLOCK) where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'  and WERKS= '" + dr["WERKS"].ToString() + "' and LGORT= '" + dr["LGORT"].ToString() + "' and LOCAT= '" + dr["LOCAT"].ToString() + "' and MRGID<>'') as T where MANDT= '" + MANDT + "' and COMCD='" + COMCD + "'and WERKS= '" + dr["WERKS"].ToString() + "' and LGORT= '" + dr["LGORT"].ToString() + "' and LOCAT= '" + dr["LOCAT"].ToString() + "'");
                }
                #endregion
                #endregion
                try
                {
                    ControlHandleDB();
                    bolResult = ControlSqlAccess.ExecSql(strSql.ToString());
                    ControlSqlAccess.CloseConnection();
                    return bolResult;
