            #region PAL311增加ErrLog
            /// <summary>
            /// PAL311增加ErrLog
            /// </summary>
            /// <param name="dtStorage"></param>
            public void AddErrorLog(DataTable dtStorage,string strType)
            {
                this.ControlMethodName = "InsertErrorLog";
                this.ControlMethodParm = "(" + dtStorage + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }
                DataErrlog objErrlog = new DataErrlog(CommonInfo.Instance.DBType, CommonInfo.Instance.DBCode.ToString(), CommonInfo.Instance.ErrType, CommonInfo.Instance.ErrCode.ToString(), UserData);
                ArrayList alColumns = new ArrayList();
                ArrayList alConditions = new ArrayList();
                ArrayList arySQL = new ArrayList();
                if(strType.Equals("Add"))
                {
                    arySQL.Clear();
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objErrlog.ResetField();

                        objErrlog.Mandt = dtStorage.Rows[i]["MANDT"].ToString();
                        objErrlog.Mblnr = dtStorage.Rows[i]["DIDNO"].ToString();
                        objErrlog.Matnr = dtStorage.Rows[i]["MATNR"].ToString();
                        objErrlog.Refid = dtStorage.Rows[i]["REFID"].ToString();
                        objErrlog.Comcd = dtStorage.Rows[i]["COMCD"].ToString();
                        objErrlog.Menge = dtStorage.Rows[i]["MENGE"].ToString();
                        objErrlog.Logtim = "GetDate()";
                        objErrlog.Maltim = "GetDate()";
                        objErrlog.Logsql = "UpdateSapInventory()_only";
                        objErrlog.Usrnm = UserData.UserId.ToString();
                        arySQL.Add(objErrlog.EntityGetInsertSql());
                    }

                }
                if (!strType.Equals("Add") && !strType.Equals("Update"))
                {
                    arySQL.Clear();
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objErrlog.ResetField();

                        objErrlog.Mandt = dtStorage.Rows[i]["MANDT"].ToString();
                        objErrlog.Mblnr = dtStorage.Rows[i]["DIDNO"].ToString();
                        objErrlog.Matnr = dtStorage.Rows[i]["MATNR"].ToString();
                        objErrlog.Refid = dtStorage.Rows[i]["REFID"].ToString();
                        objErrlog.Comcd = dtStorage.Rows[i]["COMCD"].ToString();
                        objErrlog.Menge = dtStorage.Rows[i]["MENGE"].ToString();
                        objErrlog.Logtim = "GetDate()";
                        objErrlog.Maltim = "GetDate()";
                        objErrlog.Logsql = "UpdateSapInventory()_only" + "/" + strType;
                        objErrlog.Usrnm = UserData.UserId.ToString();
                        arySQL.Add(objErrlog.EntityGetInsertSql());
                    }

                }
                if(strType.Equals("Update"))
                {
                    arySQL.Clear();
                    for (int i = 0; i < dtStorage.Rows.Count; i++)
                    {
                        alColumns.Clear();
                        alConditions.Clear();
                        objErrlog.ResetField();

                        objErrlog.Prctim = "GetDate()";
                        alConditions.Add(" MANDT='" + dtStorage.Rows[i]["MANDT"].ToString() + "'");
                        alConditions.Add(" COMCD='" + dtStorage.Rows[i]["COMCD"].ToString() + "'");
                        alConditions.Add(" MATNR='" + dtStorage.Rows[i]["MATNR"].ToString() + "'");
                        alConditions.Add(" REFID='" + dtStorage.Rows[i]["REFID"].ToString() + "'");
                        alConditions.Add(" MBLNR='" + dtStorage.Rows[i]["DIDNO"].ToString() + "'");

                        arySQL.Add(objErrlog.EntityGetUpdateSql(alConditions));
                    }
                }
                ControlHandleDB();
                ControlSqlAccess.ExecSqlArray(arySQL);
                ControlSqlAccess.CloseConnection();
            }
            #endregion

            # region 查詢連線入庫資料(G+)
            //=====================================================================================================================
            ////////////Summary by Rock Tzeng//////////////////////////////////////////////////////////////////////////////////////
            /// <summary>
            /// 查詢連線/转仓入庫資料(带PalletID)
            /// </summary> 
            /// <param name="strLocat">儲位。</param>
            /// <param name="strMblnr">單據號碼。</param>
            /// <param name="strMatnr">料號。</param>
            /// <param name="strIndat">入庫時間。</param>
            /// <param name="strInsmk">庫別。</param>
            /// <returns>
            /// DataTable。
            /// </returns>
            /// <example>
            /// <code>
            /// <remarks>
            ///  QCI.QWMS.SapData objSapData =new QCI.QWMS.SapData(strConnectionString,strMandt,strWerks,strLgort);
            ///  DataTable  dtData = objSapData.QuerySapLineInData(strLocat, strMblnr, strMatnr, strIndat, strInsmk);
            ///  Your Code Here......
            /// </remarks>
            /// </code>
            /// </example>
            ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
            public DataTable QuerySapLineInDataPallet(string strLocat, string strMblnr, string strMatnr, string strIndat,string strCharg)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "QuerySapLineInDataPallet";
                this.ControlMethodParm = "(" + strLocat + "," + strMblnr + "," + strMatnr + "," + strIndat + ",'" + strCharg + "')";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                StringBuilder sbSql = new StringBuilder();

                sbSql.AppendFormat(";WITH T AS( SELECT  MBLNR,MANDT,COMCD,MATNR,CHARG,MENGE FROM WHDWN WITH(NOLOCK) WHERE MANDT='{0}' AND COMCD='{1}' AND MTYPE='QMS_M' AND MATNR='{2}' AND CHARG='{3}' AND REFID = (Select REFID from WHDWN WITH(NOLOCK) where  MBLNR='{4}' AND REFID<>'' )  UNION ALL SELECT OMBLN AS MBLNR,MANDT,COMCD,MATNR,CHARG,ABS(MENGE) AS MENGE FROM WHLOG WITH(NOLOCK) WHERE MANDT='{0}' AND COMCD='{1}' AND MBLNR = (SELECT MBLNR FROM WHDWN WITH(NOLOCK) WHERE MANDT='{0}' AND COMCD='{1}' AND REFID =(Select REFID from WHDWN WITH(NOLOCK) where MANDT='{0}' AND COMCD='{1}' AND  MBLNR='{4}' AND REFID<>'' ) AND MATNR='{2}' AND CHARG='{3}'  AND TRNTP = 'T-' AND BWART IN ('351','303','313'))) ", MANDT, COMCD, strMatnr, strCharg, strMblnr);
                sbSql.AppendFormat("SELECT WHDWN.MANDT,WHDWN.COMCD,WERKS,LGORT,LIFNR,RMANO, '{6}' as LOCAT,WHDWN.MATNR,INSMK ,WHDWN.CHARG ,SUM(T.MENGE) AS MENGE,SUM(T.MENGE) as ALQTY,WHDWN.MBLNR ,ZEILE, T.MBLNR as OMBLNR,'' as MRGID,KOSTL,ARBPL as ARBPL,TRNTP,EBELN ,LIFNR ,'' as RMAK1,'{3}' as INDAT,ISNULL(SERNO,'') AS SERNO,ISNULL(DACOD,'') AS DACOD ,ISNULL(GRLOC,'') AS GRLOC,ISNULL(KDMAT,'') AS KDMAT  FROM WHDWN WITH(NOLOCK) LEFT JOIN T ON T.MANDT=WHDWN.MANDT AND T.COMCD=WHDWN.COMCD AND T.MATNR=WHDWN.MATNR AND T.CHARG=WHDWN.CHARG WHERE WHDWN.MANDT='{0}' AND WHDWN.COMCD='{1}' AND WERKS='{4}' AND LGORT='{5}' AND WHDWN.MBLNR='{2}' AND WHDWN.MENGE>OTQTY AND TRNTP in ('G+','M+','R+','T+') AND MTYPE='SAP'", MANDT, COMCD, strMblnr, strIndat, strWerks, strLgort, strLocat);
                sbSql.Append("GROUP BY WHDWN.MANDT,WHDWN.COMCD,WERKS,LGORT,LIFNR,RMANO, WHDWN.MATNR,INSMK ,WHDWN.CHARG ,WHDWN.MBLNR ,ZEILE, T.MBLNR,KOSTL,ARBPL,TRNTP,EBELN ,LIFNR ,SERNO,DACOD ,GRLOC,KDMAT");

                DataTable dtData = new DataTable();
                try
                {
                    dtData = ControlSqlAccess.GetDataTable(sbSql.ToString());
                }
                catch (CommonObjectsException ex)
                {
                    //讀取Common Object的真正錯誤訊息，例如ControlSqlAccess.ErrorMessage
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }//可自行增加要handle的Exception  
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }

                return dtData;
            }

            #endregion

