            public void insertQWMS_LOG(string strPALMblnr, string strSAPQty, string strQWMSQTY, string strFlag)
            {
                //設定要記錄Error Message的相關訊息
                this.ControlMethodName = "UpdateTransRemark";
                this.ControlMethodParm = "(" + strPALMblnr + strSAPQty + strQWMSQTY + ")";
                if (ControlTraceCode == "T") //若要記錄呼叫此WebMethod的log時...
                {
                    ControlHandleError("000", "", "");
                }

                StringBuilder strsql = new StringBuilder();
