            #region 查询WHDCR 厂商DateCode信息
            public DataTable QueryDateRule(string strComcd, string strVendor, string strDateCode, string strDateAfter)
            {
                this.ControlMethodName = "QueryDateCode";
                this.ControlMethodParm = "";
                if (ControlTraceCode == "T")
                {
                    ControlHandleError("000", "", "");
                }

                try
                {
                    DataTable dtData = new DataTable();
                    StringBuilder strSQL = new StringBuilder();
                    strSQL.Append("SELECT LIFNR,DC_Before,DC_After,DCLEN,TYPE,CRDAT,CRNAM,CASE WHEN MODAT='1900-01-01 00:00:00.000' THEN NULL ELSE MODAT END AS MODAT,MONAM,COMCD FROM WHDCR WITH(NOLOCK) WHERE COMCD='" + COMCD + "' ");
                    if (strVendor != "")
                    {
                        strSQL.AppendFormat("AND LIFNR='{0}' ", strVendor);
                    }
                    if (strDateCode != "")
                    {
                        strSQL.AppendFormat("AND DC_Before='{0}' ", strDateCode);
                    }
                    if (strDateAfter != "")
                    {
                        strSQL.AppendFormat("AND DC_After='{0}' ", strDateAfter);
                    }
                    strSQL.AppendFormat("order by DC_After ");

                    ControlHandleDB();
                    dtData = ControlSqlAccess.GetDataTable(strSQL.ToString());
                    ControlSqlAccess.CloseConnection();
                    return dtData;
                }
                catch (CommonObjectsException ex)
                {

                    ControlErrorDescription = ControlErrorDescription + ";" + ex.SourceErrMsg;
                    ControlExceptionType = ex.SourceExceptionType;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw ex;
                }
                catch (Exception ex)
                {
                    ControlErrorDescription = ControlErrorDescription + ";" + ex.Message;
                    ControlExceptionType = ex.GetType().FullName;
                    this.ControlPriority = "1";
                    ControlHandleError(ex.Message, ex.Source, ex.StackTrace);
                    throw new Exception("999");
                }
            }
